window.CODIGO_JAVA["documentos-cumplimiento-ms"] = {"src/main/java/com/mx/josesaid/develop/documentos/DocumentosCumplimientoApplication.java": "package com.mx.josesaid.develop.documentos;\n\nimport org.springframework.boot.SpringApplication;\nimport org.springframework.boot.autoconfigure.SpringBootApplication;\nimport org.springframework.boot.context.properties.ConfigurationPropertiesScan;\nimport org.springframework.scheduling.annotation.EnableScheduling;\n\n/** Punto de entrada de documentos-cumplimiento-ms. */\n@SpringBootApplication\n@EnableScheduling\n@ConfigurationPropertiesScan\npublic class DocumentosCumplimientoApplication {\n\n    /** Arranca documentos-cumplimiento-ms. */\n    public static void main(String[] args) {\n        SpringApplication.run(DocumentosCumplimientoApplication.class, args);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/documentos/api/DocumentosControlador.java": "package com.mx.josesaid.develop.documentos.api;\n\nimport com.mx.josesaid.develop.documentos.application.DocumentosService;\nimport com.mx.josesaid.develop.documentos.domain.Documento;\nimport com.mx.josesaid.develop.documentos.domain.SolicitudInvalidaException;\nimport com.mx.josesaid.develop.documentos.domain.TipoDocumento;\nimport com.mx.josesaid.develop.documentos.domain.VersionDocumento;\nimport jakarta.validation.Valid;\nimport jakarta.validation.constraints.NotBlank;\nimport jakarta.validation.constraints.NotNull;\nimport jakarta.validation.constraints.Size;\nimport java.io.IOException;\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport java.util.Arrays;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.UUID;\nimport org.springframework.http.HttpHeaders;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.http.MediaType;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.security.access.prepost.PreAuthorize;\nimport org.springframework.security.core.Authentication;\nimport org.springframework.web.bind.annotation.GetMapping;\nimport org.springframework.web.bind.annotation.PathVariable;\nimport org.springframework.web.bind.annotation.PostMapping;\nimport org.springframework.web.bind.annotation.RequestBody;\nimport org.springframework.web.bind.annotation.RequestMapping;\nimport org.springframework.web.bind.annotation.RequestParam;\nimport org.springframework.web.bind.annotation.RequestPart;\nimport org.springframework.web.bind.annotation.RestController;\nimport org.springframework.web.multipart.MultipartFile;\nimport org.springframework.validation.annotation.Validated;\n\n/**\n * API documental. LEGAL carga, versiona, descarga y elimina; DIRECCION solo consulta.\n * Los archivos viajan en multipart: la parte \"datos\" es JSON y la parte \"archivo\" es el documento.\n */\n@Validated\n@RestController\n@RequestMapping(\"/v1\")\npublic class DocumentosControlador {\n\n    private final DocumentosService servicio;\n\n    /** Recibe el servicio de documentos. El controlador solo valida la entrada y delega las reglas al servicio. */\n    public DocumentosControlador(DocumentosService servicio) {\n        this.servicio = servicio;\n    }\n\n    /** Crea un documento con su primera versión. Solo LEGAL puede hacerlo. Responde 201 con el documento creado. */\n    @PostMapping(value = \"/documentos\", consumes = MediaType.MULTIPART_FORM_DATA_VALUE)\n    @PreAuthorize(\"hasRole('LEGAL')\")\n    public ResponseEntity<DocumentoRespuesta> crearDocumento(@Valid @RequestPart(\"datos\") CrearDocumentoPeticion datos,\n                                                             @RequestPart(\"archivo\") MultipartFile archivo) {\n        Documento d = servicio.crearDocumento(datos.tipo(), datos.titulo(), datos.area(), datos.venceEn(), bytes(archivo));\n        return ResponseEntity.status(HttpStatus.CREATED).body(DocumentoRespuesta.de(d));\n    }\n\n    /** Agrega una nueva versión a un documento existente. Solo LEGAL puede hacerlo. Responde 201. */\n    @PostMapping(value = \"/documentos/{id}/versiones\", consumes = MediaType.MULTIPART_FORM_DATA_VALUE)\n    @PreAuthorize(\"hasRole('LEGAL')\")\n    public ResponseEntity<DocumentoRespuesta> agregarVersion(@PathVariable UUID id,\n                                                             @RequestPart(\"archivo\") MultipartFile archivo) {\n        Documento d = servicio.agregarVersion(id, bytes(archivo));\n        return ResponseEntity.status(HttpStatus.CREATED).body(DocumentoRespuesta.de(d));\n    }\n\n    /** Devuelve los datos de un documento sin la referencia de almacenamiento. LEGAL y DIRECCION pueden consultarlo. */\n    @GetMapping(\"/documentos/{id}\")\n    @PreAuthorize(\"hasAnyRole('LEGAL','DIRECCION')\")\n    public DocumentoRespuesta obtenerDocumento(@PathVariable UUID id) {\n        return DocumentoRespuesta.de(servicio.obtener(id));\n    }\n\n    /** Descarga el archivo de una versión concreta. Solo LEGAL puede hacerlo. */\n    @GetMapping(\"/documentos/{id}/versiones/{n}/descarga\")\n    @PreAuthorize(\"hasRole('LEGAL')\")\n    public ResponseEntity<byte[]> descargarVersion(@PathVariable UUID id, @PathVariable int n,\n                                                   Authentication autenticacion) {\n        DocumentosService.DescargaVersion d = servicio.descargar(id, n, autenticacion.getName());\n        return ResponseEntity.ok()\n                .header(HttpHeaders.CONTENT_DISPOSITION, \"attachment; filename=\\\"documento-\" + id + \"-v\" + n + \".bin\\\"\")\n                .contentType(MediaType.APPLICATION_OCTET_STREAM)\n                .body(d.contenido());\n    }\n\n    /** Busca documentos cuyo título contiene el texto indicado. LEGAL y DIRECCION pueden buscar. */\n    @GetMapping(value = \"/documentos\", params = \"titulo\")\n    @PreAuthorize(\"hasAnyRole('LEGAL','DIRECCION')\")\n    public List<DocumentoRespuesta> buscarPorTitulo(@RequestParam @Size(max = 200) String titulo) {\n        return servicio.buscarPorTitulo(titulo).stream().map(DocumentoRespuesta::de).toList();\n    }\n\n    /** Lista los documentos que vencen en los próximos días. LEGAL y DIRECCION pueden consultarlo. */\n    @GetMapping(\"/documentos/por-vencer\")\n    @PreAuthorize(\"hasAnyRole('LEGAL','DIRECCION')\")\n    public List<DocumentoRespuesta> porVencer(@RequestParam int dias) {\n        return servicio.porVencer(dias).stream().map(DocumentoRespuesta::de).toList();\n    }\n\n    /** Elimina un documento con un motivo. Es borrado lógico: el archivo se conserva durante el periodo de retención. Solo LEGAL puede hacerlo. */\n    @PostMapping(\"/documentos/{id}/eliminacion\")\n    @PreAuthorize(\"hasRole('LEGAL')\")\n    public DocumentoRespuesta eliminarDocumento(@PathVariable UUID id, @Valid @RequestBody MotivoPeticion p) {\n        return DocumentoRespuesta.de(servicio.eliminar(id, p.motivo()));\n    }\n\n    /** Purga un documento con una confirmación explícita. Solo LEGAL puede hacerlo. */\n    @PostMapping(\"/documentos/{id}/purga\")\n    @PreAuthorize(\"hasRole('LEGAL')\")\n    public DocumentoRespuesta purgarDocumento(@PathVariable UUID id, @Valid @RequestBody PurgaPeticion p) {\n        return DocumentoRespuesta.de(servicio.purgar(id, p.confirmacion()));\n    }\n\n    /** Devuelve el catálogo de tipos de documento. Cualquier usuario autenticado puede consultarlo. */\n    @GetMapping(\"/catalogos/tipos-documento\")\n    @PreAuthorize(\"isAuthenticated()\")\n    public List<Map<String, Object>> tiposDocumento() {\n        return Arrays.stream(TipoDocumento.values())\n                .map(t -> Map.<String, Object>of(\"tipo\", t.name(), \"retencionAnios\", t.retencionAnios()))\n                .toList();\n    }\n\n    /** Lee el archivo subido en memoria. Si no se pudo leer, responde con un error de solicitud. */\n    private static byte[] bytes(MultipartFile archivo) {\n        try {\n            return archivo.getBytes();\n        } catch (IOException e) {\n            throw new SolicitudInvalidaException(\"No se pudo leer el archivo\");\n        }\n    }\n\n    // ---- Peticiones ----\n\n    /**\n     * Datos del alta de un documento: tipo, título, área y fecha de vencimiento si aplica.\n     *\n     * @param tipo componente de tipo {@code TipoDocumento}.\n     * @param titulo componente de tipo {@code String}.\n     * @param area componente de tipo {@code String}.\n     * @param venceEn componente de tipo {@code LocalDate}.\n     */\n    public record CrearDocumentoPeticion(\n            @NotNull TipoDocumento tipo,\n            @NotBlank @Size(max = 150) String titulo,\n            @NotBlank @Size(max = 100) String area,\n            LocalDate venceEn) {\n    }\n\n    /**\n     * Motivo de la eliminación, de hasta 300 caracteres.\n     *\n     * @param motivo componente de tipo {@code String}.\n     */\n    public record MotivoPeticion(@NotBlank @Size(max = 300) String motivo) {\n    }\n\n    /**\n     * La confirmación debe ser el identificador del documento, tecleado por quien purga.\n     *\n     * @param confirmacion componente de tipo {@code String}.\n     */\n    public record PurgaPeticion(@NotBlank String confirmacion) {\n    }\n\n    // ---- Respuestas: nunca se expone la referencia de almacenamiento ----\n\n    /**\n     * Versión de un documento: número, huella SHA-256 del contenido y fecha de creación.\n     *\n     * @param numero componente de tipo {@code int}.\n     * @param hashSha256 componente de tipo {@code String}.\n     * @param creadoUtc componente de tipo {@code Instant}.\n     */\n    public record VersionRespuesta(int numero, String hashSha256, Instant creadoUtc) {\n        /** Convierte una versión del dominio en su respuesta. */\n        static VersionRespuesta de(VersionDocumento v) {\n            return new VersionRespuesta(v.numero(), v.hashSha256(), v.creadoUtc());\n        }\n    }\n\n    /**\n     * Documento tal como lo ve el cliente. Nunca incluye la referencia de almacenamiento.\n     *\n     * @param id componente de tipo {@code UUID}.\n     * @param tipo componente de tipo {@code TipoDocumento}.\n     * @param titulo componente de tipo {@code String}.\n     * @param area componente de tipo {@code String}.\n     * @param venceEn componente de tipo {@code LocalDate}.\n     * @param retencionHasta componente de tipo {@code LocalDate}.\n     * @param versionActual componente de tipo {@code int}.\n     * @param eliminado componente de tipo {@code boolean}.\n     * @param purgado componente de tipo {@code boolean}.\n     * @param versiones componente de tipo {@code List<VersionRespuesta>}.\n     */\n    public record DocumentoRespuesta(UUID id, TipoDocumento tipo, String titulo, String area, LocalDate venceEn,\n                                     LocalDate retencionHasta, int versionActual, boolean eliminado,\n                                     boolean purgado, List<VersionRespuesta> versiones) {\n        /** Convierte un documento del dominio en su respuesta, sin la referencia de almacenamiento. */\n        static DocumentoRespuesta de(Documento d) {\n            return new DocumentoRespuesta(d.getId(), d.getTipo(), d.getTitulo(), d.getArea(), d.getVenceEn(),\n                    d.getRetencionHasta(), d.getVersionActual(), d.isEliminado(), d.isPurgado(),\n                    d.getVersiones().stream().map(VersionRespuesta::de).toList());\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/documentos/api/ManejadorErrores.java": "package com.mx.josesaid.develop.documentos.api;\n\nimport com.mx.josesaid.develop.documentos.domain.ConflictoException;\nimport com.mx.josesaid.develop.documentos.domain.RecursoNoEncontradoException;\nimport com.mx.josesaid.develop.documentos.domain.ReglaDeNegocioException;\nimport com.mx.josesaid.develop.documentos.domain.SolicitudInvalidaException;\nimport java.net.URI;\nimport org.springframework.dao.OptimisticLockingFailureException;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.http.MediaType;\nimport org.springframework.http.ProblemDetail;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.web.multipart.support.MissingServletRequestPartException;\nimport org.springframework.web.bind.annotation.ExceptionHandler;\nimport org.springframework.web.bind.annotation.RestControllerAdvice;\nimport org.springframework.web.multipart.MaxUploadSizeExceededException;\n\n/** Convierte excepciones en respuestas RFC 9457 (application/problem+json). */\n@RestControllerAdvice\npublic class ManejadorErrores {\n\n    /** Convierte una regla de negocio incumplida en 422. */\n    @ExceptionHandler(ReglaDeNegocioException.class)\n    ResponseEntity<ProblemDetail> reglaDeNegocio(ReglaDeNegocioException e) {\n        return respuesta(HttpStatus.UNPROCESSABLE_ENTITY, \"regla-de-negocio\", e.getMessage());\n    }\n\n    /** Convierte un recurso inexistente en 404. */\n    @ExceptionHandler(RecursoNoEncontradoException.class)\n    ResponseEntity<ProblemDetail> noEncontrado(RecursoNoEncontradoException e) {\n        return respuesta(HttpStatus.NOT_FOUND, \"recurso-no-encontrado\", e.getMessage());\n    }\n\n    /** Convierte un conflicto de estado, por ejemplo eliminar dentro de retención, en 409. */\n    @ExceptionHandler(ConflictoException.class)\n    ResponseEntity<ProblemDetail> conflicto(ConflictoException e) {\n        return respuesta(HttpStatus.CONFLICT, \"conflicto-de-estado\", e.getMessage());\n    }\n\n    /** Convierte una solicitud inválida en 400. */\n    @ExceptionHandler(SolicitudInvalidaException.class)\n    ResponseEntity<ProblemDetail> solicitudInvalida(SolicitudInvalidaException e) {\n        return respuesta(HttpStatus.BAD_REQUEST, \"solicitud-invalida\", e.getMessage());\n    }\n\n    /** Responde 400 cuando falta la parte del archivo en la carga. */\n    @ExceptionHandler(MissingServletRequestPartException.class)\n    ResponseEntity<ProblemDetail> parteFaltante(MissingServletRequestPartException e) {\n        return respuesta(HttpStatus.BAD_REQUEST, \"solicitud-invalida\",\n                \"Falta la parte multipart requerida: \" + e.getRequestPartName());\n    }\n\n    /** Responde 413 cuando el archivo supera el tamaño permitido. */\n    @ExceptionHandler(MaxUploadSizeExceededException.class)\n    ResponseEntity<ProblemDetail> archivoGrande(MaxUploadSizeExceededException e) {\n        return respuesta(HttpStatus.CONTENT_TOO_LARGE, \"archivo-demasiado-grande\",\n                \"El archivo supera el tamaño máximo permitido\");\n    }\n\n    /** Dos usuarios modificaron el mismo documento: el segundo recibe 409 y debe volver a leer. */\n    @ExceptionHandler(OptimisticLockingFailureException.class)\n    ResponseEntity<ProblemDetail> concurrencia(OptimisticLockingFailureException e) {\n        return respuesta(HttpStatus.CONFLICT, \"conflicto-concurrencia\",\n                \"El documento cambió mientras se procesaba. Vuelva a leerlo e intente de nuevo.\");\n    }\n\n    /** Construye la respuesta de error con el estado, el tipo y el detalle indicados. */\n    private static ResponseEntity<ProblemDetail> respuesta(HttpStatus estado, String slug, String detalle) {\n        ProblemDetail problema = ProblemDetail.forStatusAndDetail(estado, detalle);\n        problema.setTitle(estado.getReasonPhrase());\n        problema.setType(URI.create(\"urn:josesaid:documentos-cumplimiento:error:\" + slug));\n        return ResponseEntity.status(estado).contentType(MediaType.APPLICATION_PROBLEM_JSON).body(problema);\n    }\n\n    /** Convierte parámetros inválidos en 400 sin revelar detalles internos. */\n    @org.springframework.web.bind.annotation.ExceptionHandler(jakarta.validation.ConstraintViolationException.class)\n    org.springframework.http.ProblemDetail parametrosInvalidos(jakarta.validation.ConstraintViolationException e) {\n        return org.springframework.http.ProblemDetail.forStatusAndDetail(\n                org.springframework.http.HttpStatus.BAD_REQUEST, \"Revise los parámetros indicados\");\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/documentos/application/AlmacenDocumentos.java": "package com.mx.josesaid.develop.documentos.application;\n\nimport java.util.UUID;\n\n/** Puerto de almacenamiento de archivos. La implementación los guarda cifrados. */\npublic interface AlmacenDocumentos {\n    String referencia(UUID documentoId, int numero);\n    void guardar(String referencia, byte[] contenido);\n    byte[] leer(String referencia);\n    /** Borra el archivo físico. Idempotente: un archivo que ya no existe no es error. */\n    void borrar(String referencia);\n}\n", "src/main/java/com/mx/josesaid/develop/documentos/application/DocumentosService.java": "package com.mx.josesaid.develop.documentos.application;\n\nimport com.mx.josesaid.develop.documentos.domain.ConflictoException;\nimport com.mx.josesaid.develop.documentos.domain.Documento;\nimport com.mx.josesaid.develop.documentos.domain.DocumentoRepositorio;\nimport com.mx.josesaid.develop.documentos.domain.RecursoNoEncontradoException;\nimport com.mx.josesaid.develop.documentos.domain.SolicitudInvalidaException;\nimport com.mx.josesaid.develop.documentos.domain.TipoDocumento;\nimport com.mx.josesaid.develop.documentos.domain.VersionDocumento;\nimport io.micrometer.core.instrument.MeterRegistry;\nimport java.security.MessageDigest;\nimport java.security.NoSuchAlgorithmException;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport java.util.HexFormat;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.UUID;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\n\n/** Casos de uso documentales: carga, versiones, descarga auditada, eliminación y purga con retención, y alertas. */\n@Service\npublic class DocumentosService {\n\n    private static final Logger log = LoggerFactory.getLogger(DocumentosService.class);\n    private static final int MAX_DIAS = 3650;\n\n    private final DocumentoRepositorio documentos;\n    private final AlmacenDocumentos almacen;\n    private final PublicadorEventos eventos;\n    private final Clock reloj;\n    private final MeterRegistry metricas;\n    private final int umbralDias;\n\n    /** Recibe el repositorio, el almacén de archivos, el publicador de eventos, las métricas y el reloj. */\n    public DocumentosService(DocumentoRepositorio documentos, AlmacenDocumentos almacen, PublicadorEventos eventos,\n                             Clock reloj, MeterRegistry metricas,\n                             @Value(\"${documentos.alertas.umbral-dias:30}\") int umbralDias) {\n        this.documentos = documentos;\n        this.almacen = almacen;\n        this.eventos = eventos;\n        this.reloj = reloj;\n        this.metricas = metricas;\n        this.umbralDias = umbralDias;\n    }\n\n    /**\n     * Contenido descifrado de una versión, ya verificado contra su hash.\n     *\n     * @param version componente de tipo {@code VersionDocumento}.\n     * @param contenido componente de tipo {@code byte[]}.\n     */\n    public record DescargaVersion(VersionDocumento version, byte[] contenido) {\n    }\n\n    /** Crea el documento y guarda su primera versión. Calcula la huella SHA-256 del contenido y guarda el archivo en el almacén. Rechaza contenido vacío. */\n    @Transactional\n    public Documento crearDocumento(TipoDocumento tipo, String titulo, String area, LocalDate venceEn, byte[] contenido) {\n        exigirContenido(contenido);\n        UUID id = UUID.randomUUID();\n        String ref = almacen.referencia(id, 1);\n        Documento d = Documento.crear(id, tipo, titulo, area, venceEn, hoy(), sha256(contenido), ref, Instant.now(reloj));\n        almacen.guardar(ref, contenido);\n        Documento guardado = documentos.guardar(d);\n        metricas.counter(\"documentos.creados\").increment();\n        metricas.counter(\"versiones.creadas\").increment();\n        publicarVersion(guardado, 1);\n        return guardado;\n    }\n\n    /** Agrega una versión nueva. La versión anterior no se modifica: el historial siempre se conserva. */\n    @Transactional\n    public Documento agregarVersion(UUID id, byte[] contenido) {\n        exigirContenido(contenido);\n        Documento d = cargar(id);\n        String hash = sha256(contenido);\n        LocalDate hoy = hoy();\n        d.validarNuevaVersion(hash, hoy);\n        int numero = d.getVersionActual() + 1;\n        String ref = almacen.referencia(id, numero);\n        almacen.guardar(ref, contenido);\n        d.agregarVersion(hash, ref, hoy, Instant.now(reloj));\n        Documento guardado = documentos.guardar(d);\n        metricas.counter(\"versiones.creadas\").increment();\n        publicarVersion(guardado, numero);\n        return guardado;\n    }\n\n    /** Devuelve un documento por identificador. Si no existe, lanza RecursoNoEncontradoException. */\n    @Transactional(readOnly = true)\n    public Documento obtener(UUID id) {\n        return cargar(id);\n    }\n\n    /** Devuelve el archivo de una versión. Antes de devolverlo verifica que su huella coincida con la guardada; si no coincide, falla. */\n    @Transactional(readOnly = true)\n    public DescargaVersion descargar(UUID id, int numero, String usuario) {\n        Documento d = cargar(id);\n        if (d.isPurgado()) {\n            throw new ConflictoException(\"El contenido del documento fue purgado\");\n        }\n        VersionDocumento v = d.version(numero)\n                .orElseThrow(() -> new RecursoNoEncontradoException(\"Versión no encontrada: \" + numero));\n        byte[] contenido = almacen.leer(v.almacenamientoRef());\n        if (!sha256(contenido).equals(v.hashSha256())) {\n            throw new IllegalStateException(\"La versión \" + numero + \" no pasó la verificación de integridad\");\n        }\n        log.info(\"AUDITORIA documento={} version={} accion=DESCARGA usuario={}\", id, numero, usuario);\n        return new DescargaVersion(v, contenido);\n    }\n\n    /** Elimina el documento con un motivo, de forma lógica. Dentro del periodo de retención se rechaza. */\n    @Transactional\n    public Documento eliminar(UUID id, String motivo) {\n        Documento d = cargar(id);\n        d.eliminar(motivo, hoy(), Instant.now(reloj));\n        log.info(\"AUDITORIA documento={} accion=ELIMINACION\", id);\n        return documentos.guardar(d);\n    }\n\n    /** Purga física tras la eliminación: borra el contenido de todas las versiones; metadatos y hashes permanecen. */\n    @Transactional\n    public Documento purgar(UUID id, String confirmacion) {\n        Documento d = cargar(id);\n        d.purgar(confirmacion, hoy(), Instant.now(reloj));\n        for (VersionDocumento v : d.getVersiones()) {\n            almacen.borrar(v.almacenamientoRef());\n        }\n        log.info(\"AUDITORIA documento={} accion=PURGA\", id);\n        return documentos.guardar(d);\n    }\n\n    /** Hasta 15 documentos cuyo título contiene el texto. Pide al menos 3 caracteres. */\n    @Transactional(readOnly = true)\n    public List<Documento> buscarPorTitulo(String texto) {\n        String limpio = texto == null ? \"\" : texto.trim();\n        if (limpio.length() < 3) {\n            throw new SolicitudInvalidaException(\"La búsqueda necesita al menos 3 caracteres\");\n        }\n        return documentos.buscarPorTitulo(limpio, 15);\n    }\n\n    /** Lista los documentos que vencen en los próximos días. */\n    @Transactional(readOnly = true)\n    public List<Documento> porVencer(int dias) {\n        if (dias < 0 || dias > MAX_DIAS) {\n            throw new SolicitudInvalidaException(\"dias debe estar entre 0 y \" + MAX_DIAS);\n        }\n        LocalDate hoy = hoy();\n        return documentos.buscarVencenEntre(hoy, hoy.plusDays(dias));\n    }\n\n    /** Tarea diaria: emite alertas de permisos por vencer y marca retenciones vencidas para revisión. */\n    @Transactional\n    public int procesarVencimientos() {\n        LocalDate hoy = hoy();\n        int alertas = 0;\n        for (Documento d : documentos.buscarVencenEntre(hoy, hoy.plusDays(umbralDias))) {\n            if (d.necesitaAlertaVencimiento(hoy, umbralDias)) {\n                d.registrarAlertaVencimiento();\n                documentos.guardar(d);\n                eventos.publicar(new EventoDominio(\"permiso-por-vencer\", d.getId().toString(), Map.of(\n                        \"documento_id\", d.getId().toString(),\n                        \"vence_en\", d.getVenceEn().toString())));\n                alertas++;\n            }\n        }\n        for (Documento d : documentos.buscarActivosConRetencionVencida(hoy)) {\n            if (d.necesitaRevisionRetencion(hoy)) {\n                d.marcarRevisionRetencion();\n                documentos.guardar(d);\n                log.info(\"Retención vencida, documento marcado para revisión: {}\", d.getId());\n            }\n        }\n        return alertas;\n    }\n\n    /** Carga un documento o lanza RecursoNoEncontradoException si no existe. */\n    private Documento cargar(UUID id) {\n        return documentos.buscarPorId(id)\n                .orElseThrow(() -> new RecursoNoEncontradoException(\"Documento no encontrado: \" + id));\n    }\n\n    /** Publica el evento de la nueva versión para que otros servicios lo reciban. */\n    private void publicarVersion(Documento d, int numero) {\n        eventos.publicar(new EventoDominio(\"documento-version-creada\", d.getId().toString(), Map.of(\n                \"documento_id\", d.getId().toString(),\n                \"numero\", numero)));\n    }\n\n    /** Devuelve la fecha de hoy en la zona de México. */\n    private LocalDate hoy() {\n        return LocalDate.now(reloj);\n    }\n\n    /** Rechaza un contenido nulo o vacío antes de guardarlo. */\n    private static void exigirContenido(byte[] contenido) {\n        if (contenido == null || contenido.length == 0) {\n            throw new SolicitudInvalidaException(\"El archivo es obligatorio y no puede estar vacío\");\n        }\n    }\n\n    /** Calcula la huella SHA-256 del contenido en hexadecimal. Sirve para detectar cambios en el archivo guardado. */\n    static String sha256(byte[] contenido) {\n        try {\n            return HexFormat.of().formatHex(MessageDigest.getInstance(\"SHA-256\").digest(contenido));\n        } catch (NoSuchAlgorithmException e) {\n            throw new IllegalStateException(\"SHA-256 no disponible\", e);\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/documentos/application/EventoDominio.java": "package com.mx.josesaid.develop.documentos.application;\n\nimport java.util.Map;\n\n/**\n * Evento de negocio. Se guarda en el outbox y luego se envía a Kafka.\n *\n * @param tipo componente de tipo {@code String}.\n * @param agregadoId componente de tipo {@code String}.\n * @param datos componente de tipo {@code Map<String, Object>}.\n */\npublic record EventoDominio(String tipo, String agregadoId, Map<String, Object> datos) {\n}\n", "src/main/java/com/mx/josesaid/develop/documentos/application/PublicadorEventos.java": "package com.mx.josesaid.develop.documentos.application;\n\n/** Publica los eventos de dominio de documentos para que otros servicios reaccionen. */\npublic interface PublicadorEventos {\n    void publicar(EventoDominio evento);\n}\n", "src/main/java/com/mx/josesaid/develop/documentos/config/PropiedadesJwt.java": "package com.mx.josesaid.develop.documentos.config;\n\nimport java.time.Duration;\nimport org.springframework.boot.context.properties.ConfigurationProperties;\n\n/**\n * Propiedades del emisor de tokens, enlazadas desde {@code documentos.jwt}.\n *\n * @param jwksUri URL del JWKS de usuarios-accesos-ms con la clave pública para validar tokens\n * @param duracion vida del token de acceso\n * @param emisor   valor del claim {@code iss}\n */\n@ConfigurationProperties(prefix = \"documentos.jwt\")\npublic record PropiedadesJwt(String jwksUri, Duration duracion, String emisor) {\n}\n", "src/main/java/com/mx/josesaid/develop/documentos/config/RelojConfig.java": "package com.mx.josesaid.develop.documentos.config;\n\nimport java.time.Clock;\nimport java.time.ZoneId;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\n\n/** Reloj en UTC. Inyectarlo permite probar las reglas de tiempo sin depender de la hora real. */\n@Configuration\npublic class RelojConfig {\n\n    /** Reloj del sistema en UTC. */\n    @Bean\n    Clock reloj() {\n        return Clock.system(ZoneId.of(\"America/Mexico_City\"));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/documentos/config/SeguridadConfig.java": "package com.mx.josesaid.develop.documentos.config;\n\nimport org.springframework.security.access.hierarchicalroles.RoleHierarchy;\nimport org.springframework.security.access.hierarchicalroles.RoleHierarchyImpl;\n\nimport com.mx.josesaid.develop.documentos.seguridad.EntradaNoAutorizada;\n\nimport com.mx.josesaid.develop.documentos.seguridad.RevocacionSesiones;\nimport com.mx.josesaid.develop.documentos.seguridad.ValidadorRevocacion;\nimport org.springframework.security.oauth2.core.DelegatingOAuth2TokenValidator;\nimport org.springframework.security.oauth2.jwt.JwtValidators;\n\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;\nimport org.springframework.security.config.annotation.web.builders.HttpSecurity;\nimport org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;\nimport org.springframework.security.config.http.SessionCreationPolicy;\nimport org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;\nimport org.springframework.security.crypto.password.PasswordEncoder;\nimport org.springframework.security.oauth2.jwt.JwtDecoder;\nimport org.springframework.security.oauth2.jwt.NimbusJwtDecoder;\nimport org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationConverter;\nimport org.springframework.security.oauth2.server.resource.authentication.JwtGrantedAuthoritiesConverter;\nimport org.springframework.security.web.SecurityFilterChain;\n\n/**\n * Seguridad del servicio: API sin estado, JWT como resource server y autorización por rol.\n *\n * <p>Solo el login y el health son públicos. Todo lo demás exige un token válido.\n */\n@Configuration\n@EnableWebSecurity\n@EnableMethodSecurity\npublic class SeguridadConfig {\n\n    /** Cadena de seguridad: exige JWT válido y reglas por rol en cada endpoint. */\n    @Bean\n    SecurityFilterChain cadenaSeguridad(HttpSecurity http) throws Exception {\n        http\n            .csrf(csrf -> csrf.disable()) // API sin cookies de sesión: no aplica CSRF\n            .sessionManagement(sesion -> sesion.sessionCreationPolicy(SessionCreationPolicy.STATELESS))\n            .authorizeHttpRequests(auth -> auth\n                .requestMatchers(\"/actuator/health\", \"/actuator/health/**\", \"/actuator/prometheus\").permitAll()\n                .anyRequest().authenticated())\n            .oauth2ResourceServer(oauth -> oauth.authenticationEntryPoint(new EntradaNoAutorizada()).jwt(jwt -> jwt.jwtAuthenticationConverter(convertidorJwt())));\n        return http.build();\n    }\n\n    /** Convierte el claim {@code roles} en autoridades {@code ROLE_*}. */\n    @Bean\n    JwtAuthenticationConverter convertidorJwt() {\n        JwtGrantedAuthoritiesConverter autoridades = new JwtGrantedAuthoritiesConverter();\n        autoridades.setAuthoritiesClaimName(\"roles\");\n        autoridades.setAuthorityPrefix(\"ROLE_\");\n        JwtAuthenticationConverter convertidor = new JwtAuthenticationConverter();\n        convertidor.setJwtGrantedAuthoritiesConverter(autoridades);\n        return convertidor;\n    }\n\n    /** Valida la firma con la clave pública que publica usuarios-accesos-ms (JWKS). */\n    @Bean\n    JwtDecoder jwtDecoder(PropiedadesJwt propiedades, RevocacionSesiones revocaciones) {\n        var decoder = NimbusJwtDecoder.withJwkSetUri(propiedades.jwksUri()).build();\n        decoder.setJwtValidator(new DelegatingOAuth2TokenValidator<>(JwtValidators.createDefault(),\n                new ValidadorRevocacion(revocaciones)));\n        return decoder;\n    }\n\n    /** Codificador de contraseñas BCrypt para el servicio. */\n    @Bean\n    PasswordEncoder passwordEncoder() {\n        return new BCryptPasswordEncoder();\n    }\n\n    /** ADMIN puede hacer todo: hereda todos los roles de negocio. */\n    @Bean\n    RoleHierarchy jerarquiaRoles() {\n        return RoleHierarchyImpl.withDefaultRolePrefix()\n                .role(\"ADMIN\").implies(\"FINANZAS\", \"CONTADOR\", \"VENTAS\", \"COMPRAS\", \"ALMACEN\", \"OPERACIONES\", \"CALIDAD\", \"DIRECCION\", \"LEGAL\", \"JEFE_AREA\")\n                .build();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/documentos/domain/ConflictoException.java": "package com.mx.josesaid.develop.documentos.domain;\n\n/** Conflicto con el estado actual del documento. HTTP 409. */\npublic class ConflictoException extends RuntimeException {\n    /** Crea la excepción con el motivo del conflicto. */\n    public ConflictoException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/documentos/domain/Documento.java": "package com.mx.josesaid.develop.documentos.domain;\n\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport java.util.ArrayList;\nimport java.util.Collections;\nimport java.util.List;\nimport java.util.Optional;\nimport java.util.UUID;\n\n/**\n * Documento legal con versiones. Cada cambio de contenido crea una versión nueva; las publicadas no cambian.\n * Un documento vencido no recibe versiones: se registra uno nuevo. Eliminar exige retención vencida y motivo.\n * Purgar borra el contenido físico de un documento eliminado; los metadatos y los hashes se conservan.\n */\npublic class Documento {\n\n    private final UUID id;\n    private final TipoDocumento tipo;\n    private final String titulo;\n    private final String area;\n    private final LocalDate venceEn;\n    private final LocalDate retencionHasta;\n    private final List<VersionDocumento> versiones;\n    private boolean eliminado;\n    private String motivoEliminacion;\n    private Instant eliminadoUtc;\n    private boolean revisionRetencion;\n    private boolean alertaVencimientoEmitida;\n    private boolean purgado;\n    private Instant purgadoUtc;\n\n    /** Constructor privado: los documentos se crean con sus fábricas y no con new. */\n    private Documento(UUID id, TipoDocumento tipo, String titulo, String area, LocalDate venceEn,\n                      LocalDate retencionHasta, List<VersionDocumento> versiones, boolean eliminado,\n                      String motivoEliminacion, Instant eliminadoUtc, boolean revisionRetencion,\n                      boolean alertaVencimientoEmitida, boolean purgado, Instant purgadoUtc) {\n        this.id = id;\n        this.tipo = tipo;\n        this.titulo = titulo;\n        this.area = area;\n        this.venceEn = venceEn;\n        this.retencionHasta = retencionHasta;\n        this.versiones = new ArrayList<>(versiones);\n        this.eliminado = eliminado;\n        this.motivoEliminacion = motivoEliminacion;\n        this.eliminadoUtc = eliminadoUtc;\n        this.revisionRetencion = revisionRetencion;\n        this.alertaVencimientoEmitida = alertaVencimientoEmitida;\n        this.purgado = purgado;\n        this.purgadoUtc = purgadoUtc;\n    }\n\n    /** Crea el documento con su versión 1. La retención se calcula desde hoy según el tipo. */\n    public static Documento crear(UUID id, TipoDocumento tipo, String titulo, String area, LocalDate venceEn,\n                                  LocalDate hoy, String hashSha256, String ref, Instant ahora) {\n        if (tipo == null) {\n            throw new SolicitudInvalidaException(\"El tipo de documento es obligatorio\");\n        }\n        if (titulo == null || titulo.isBlank()) {\n            throw new SolicitudInvalidaException(\"El título es obligatorio\");\n        }\n        if (area == null || area.isBlank()) {\n            throw new SolicitudInvalidaException(\"El área es obligatoria\");\n        }\n        if (tipo == TipoDocumento.PERMISO && venceEn == null) {\n            throw new ReglaDeNegocioException(\"Un permiso requiere fecha de vencimiento\");\n        }\n        if (venceEn != null && venceEn.isBefore(hoy)) {\n            throw new ReglaDeNegocioException(\"La fecha de vencimiento ya pasó; registre un documento vigente\");\n        }\n        List<VersionDocumento> primera = List.of(new VersionDocumento(UUID.randomUUID(), 1, hashSha256, ref, ahora));\n        return new Documento(id, tipo, titulo.trim(), area.trim(), venceEn, hoy.plusYears(tipo.retencionAnios()),\n                primera, false, null, null, false, false, false, null);\n    }\n\n    /** Reconstruye un documento desde la base de datos sin aplicar reglas de negocio. */\n    public static Documento reconstruir(UUID id, TipoDocumento tipo, String titulo, String area, LocalDate venceEn,\n                                        LocalDate retencionHasta, List<VersionDocumento> versiones, boolean eliminado,\n                                        String motivoEliminacion, Instant eliminadoUtc, boolean revisionRetencion,\n                                        boolean alertaVencimientoEmitida, boolean purgado, Instant purgadoUtc) {\n        return new Documento(id, tipo, titulo, area, venceEn, retencionHasta, versiones, eliminado,\n                motivoEliminacion, eliminadoUtc, revisionRetencion, alertaVencimientoEmitida, purgado, purgadoUtc);\n    }\n\n    /** Lanza error si la nueva versión no puede crearse. Se llama antes de guardar el archivo. */\n    public void validarNuevaVersion(String hashSha256, LocalDate hoy) {\n        if (eliminado) {\n            throw new ConflictoException(\"El documento fue eliminado; no admite versiones\");\n        }\n        if (vencido(hoy)) {\n            throw new ConflictoException(\"El documento venció; registre un documento nuevo\");\n        }\n        if (hashSha256.equals(ultimaVersion().hashSha256())) {\n            throw new ConflictoException(\"El contenido no cambió; no se crea una versión nueva\");\n        }\n    }\n\n    /** Agrega una versión nueva con su huella y su referencia de almacenamiento. Devuelve la versión creada. */\n    public VersionDocumento agregarVersion(String hashSha256, String ref, LocalDate hoy, Instant ahora) {\n        validarNuevaVersion(hashSha256, hoy);\n        VersionDocumento nueva = new VersionDocumento(UUID.randomUUID(), getVersionActual() + 1, hashSha256, ref, ahora);\n        versiones.add(nueva);\n        return nueva;\n    }\n\n    /** Elimina el documento de forma lógica. El motivo es obligatorio, no puede eliminarse dos veces y no se permite dentro de la retención. */\n    public void eliminar(String motivo, LocalDate hoy, Instant ahora) {\n        if (motivo == null || motivo.isBlank()) {\n            throw new SolicitudInvalidaException(\"El motivo de eliminación es obligatorio\");\n        }\n        if (eliminado) {\n            throw new ConflictoException(\"El documento ya fue eliminado\");\n        }\n        if (!hoy.isAfter(retencionHasta)) {\n            throw new ConflictoException(\"No se puede eliminar dentro del periodo de retención (hasta \" + retencionHasta + \")\");\n        }\n        this.eliminado = true;\n        this.motivoEliminacion = motivo.trim();\n        this.eliminadoUtc = ahora;\n    }\n\n    /**\n     * Purga física: marca el documento como purgado. El llamador borra después los archivos de cada versión.\n     * Exige eliminación previa, retención vencida y confirmación tecleada con el identificador del documento.\n     */\n    public void purgar(String confirmacion, LocalDate hoy, Instant ahora) {\n        if (!eliminado) {\n            throw new ConflictoException(\"Solo se purga un documento eliminado\");\n        }\n        if (purgado) {\n            throw new ConflictoException(\"El documento ya fue purgado\");\n        }\n        if (!hoy.isAfter(retencionHasta)) {\n            throw new ConflictoException(\"No se puede purgar dentro del periodo de retención (hasta \" + retencionHasta + \")\");\n        }\n        if (confirmacion == null || !confirmacion.trim().equals(id.toString())) {\n            throw new SolicitudInvalidaException(\"La confirmación debe ser el identificador del documento\");\n        }\n        this.purgado = true;\n        this.purgadoUtc = ahora;\n    }\n\n    /** Indica si el documento ya venció a la fecha indicada. */\n    public boolean vencido(LocalDate hoy) {\n        return venceEn != null && venceEn.isBefore(hoy);\n    }\n\n    /** Un permiso entra en alerta una sola vez, cuando su vencimiento cae dentro del umbral. */\n    public boolean necesitaAlertaVencimiento(LocalDate hoy, int umbralDias) {\n        if (tipo != TipoDocumento.PERMISO || eliminado || alertaVencimientoEmitida || venceEn == null) {\n            return false;\n        }\n        return !venceEn.isBefore(hoy) && !venceEn.isAfter(hoy.plusDays(umbralDias));\n    }\n\n    /** Marca que la alerta de vencimiento ya se emitió, para no repetirla. */\n    public void registrarAlertaVencimiento() {\n        this.alertaVencimientoEmitida = true;\n    }\n\n    /** Indica si el documento ya cumplió su retención y debe revisarse. */\n    public boolean necesitaRevisionRetencion(LocalDate hoy) {\n        return !eliminado && !revisionRetencion && hoy.isAfter(retencionHasta);\n    }\n\n    /** Marca que la revisión de retención ya se hizo. */\n    public void marcarRevisionRetencion() {\n        this.revisionRetencion = true;\n    }\n\n    /** Devuelve la versión con ese número, si existe. */\n    public Optional<VersionDocumento> version(int numero) {\n        return versiones.stream().filter(v -> v.numero() == numero).findFirst();\n    }\n\n    /** Devuelve la versión más reciente. */\n    private VersionDocumento ultimaVersion() {\n        return versiones.get(versiones.size() - 1);\n    }\n\n    /** Devuelve el identificador del documento. */\n    public UUID getId() { return id; }\n    /** Devuelve el tipo de documento. */\n    public TipoDocumento getTipo() { return tipo; }\n    /** Devuelve el título. */\n    public String getTitulo() { return titulo; }\n    /** Devuelve el área responsable. */\n    public String getArea() { return area; }\n    /** Devuelve la fecha de vencimiento, si aplica. */\n    public LocalDate getVenceEn() { return venceEn; }\n    /** Devuelve la fecha hasta la que se conserva el documento. */\n    public LocalDate getRetencionHasta() { return retencionHasta; }\n    /** Devuelve las versiones en orden, en una vista de solo lectura. */\n    public List<VersionDocumento> getVersiones() { return Collections.unmodifiableList(versiones); }\n    /** Devuelve el número de la última versión. */\n    public int getVersionActual() { return versiones.size(); }\n    /** Indica si el documento fue eliminado de forma lógica. */\n    public boolean isEliminado() { return eliminado; }\n    /** Devuelve el motivo de la eliminación, o nulo si no fue eliminado. */\n    public String getMotivoEliminacion() { return motivoEliminacion; }\n    /** Devuelve la fecha de eliminación en UTC. */\n    public Instant getEliminadoUtc() { return eliminadoUtc; }\n    /** Indica si el documento está marcado para revisión de retención. */\n    public boolean isRevisionRetencion() { return revisionRetencion; }\n    /** Indica si ya se emitió la alerta de vencimiento. */\n    public boolean isAlertaVencimientoEmitida() { return alertaVencimientoEmitida; }\n    /** Indica si el contenido ya fue purgado. */\n    public boolean isPurgado() { return purgado; }\n    /** Devuelve la fecha de la purga en UTC. */\n    public Instant getPurgadoUtc() { return purgadoUtc; }\n}\n", "src/main/java/com/mx/josesaid/develop/documentos/domain/DocumentoRepositorio.java": "package com.mx.josesaid.develop.documentos.domain;\n\nimport java.time.LocalDate;\nimport java.util.List;\nimport java.util.Optional;\nimport java.util.UUID;\n\n/** Puerto para guardar y consultar documentos, sin depender de JPA. */\npublic interface DocumentoRepositorio {\n    Documento guardar(Documento documento);\n    Optional<Documento> buscarPorId(UUID id);\n    List<Documento> buscarVencenEntre(LocalDate desde, LocalDate hasta);\n    List<Documento> buscarActivosConRetencionVencida(LocalDate hoy);\n\n    /** Documentos no eliminados cuyo título contiene el texto (sin distinguir mayúsculas), por título. */\n    List<Documento> buscarPorTitulo(String texto, int limite);\n}\n", "src/main/java/com/mx/josesaid/develop/documentos/domain/RecursoNoEncontradoException.java": "package com.mx.josesaid.develop.documentos.domain;\n\n/** El recurso no existe. HTTP 404. */\npublic class RecursoNoEncontradoException extends RuntimeException {\n    /** Crea la excepción con el mensaje que se mostrará al cliente. */\n    public RecursoNoEncontradoException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/documentos/domain/ReglaDeNegocioException.java": "package com.mx.josesaid.develop.documentos.domain;\n\n/** Una operación viola una regla de negocio. HTTP 422. */\npublic class ReglaDeNegocioException extends RuntimeException {\n    /** Crea la excepción con el mensaje de la regla incumplida. */\n    public ReglaDeNegocioException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/documentos/domain/SolicitudInvalidaException.java": "package com.mx.josesaid.develop.documentos.domain;\n\n/** Datos de forma inválidos. HTTP 400. */\npublic class SolicitudInvalidaException extends RuntimeException {\n    /** Crea la excepción con el motivo de la solicitud inválida. */\n    public SolicitudInvalidaException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/documentos/domain/TipoDocumento.java": "package com.mx.josesaid.develop.documentos.domain;\n\n/** Tipos de documento y su retención mínima desde la carga. Confirmada por Legal: contrato 10, permiso 5, registro legal 10 años. */\npublic enum TipoDocumento {\n    CONTRATO(10),\n    PERMISO(5),\n    REGISTRO_LEGAL(10);\n\n    private final int retencionAnios;\n\n    TipoDocumento(int retencionAnios) {\n        this.retencionAnios = retencionAnios;\n    }\n\n    /** Años que el documento debe conservarse antes de poder eliminarse. */\n    public int retencionAnios() {\n        return retencionAnios;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/documentos/domain/VersionDocumento.java": "package com.mx.josesaid.develop.documentos.domain;\n\nimport java.time.Instant;\nimport java.util.UUID;\n\n/**\n * Versión inmutable de un documento. La referencia apunta al archivo cifrado; nunca se expone en la API.\n *\n * @param id componente de tipo {@code UUID}.\n * @param numero componente de tipo {@code int}.\n * @param hashSha256 componente de tipo {@code String}.\n * @param almacenamientoRef componente de tipo {@code String}.\n * @param creadoUtc componente de tipo {@code Instant}.\n */\npublic record VersionDocumento(UUID id, int numero, String hashSha256, String almacenamientoRef, Instant creadoUtc) {\n}\n", "src/main/java/com/mx/josesaid/develop/documentos/infrastructure/almacen/AlmacenArchivosLocal.java": "package com.mx.josesaid.develop.documentos.infrastructure.almacen;\n\nimport com.mx.josesaid.develop.documentos.application.AlmacenDocumentos;\nimport com.mx.josesaid.develop.documentos.infrastructure.seguridad.ProtectorArchivos;\nimport java.io.IOException;\nimport java.nio.file.Files;\nimport java.nio.file.Path;\nimport java.nio.file.StandardOpenOption;\nimport java.util.UUID;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.stereotype.Component;\n\n/** Almacén en el volumen del contenedor. Cada archivo se cifra antes de escribirse. */\n@Component\npublic class AlmacenArchivosLocal implements AlmacenDocumentos {\n\n    private final Path raiz;\n    private final ProtectorArchivos protector;\n\n    /** Recibe el directorio base donde se guardan los archivos. Ahí se crean las carpetas de cada documento. */\n    public AlmacenArchivosLocal(@Value(\"${documentos.almacen.directorio}\") String directorio,\n                                ProtectorArchivos protector) {\n        this.raiz = Path.of(directorio).toAbsolutePath().normalize();\n        this.protector = protector;\n    }\n\n    /** Construye la referencia de almacenamiento de una versión a partir de su documento y número. La referencia nunca sale de la API. */\n    @Override\n    public String referencia(UUID documentoId, int numero) {\n        return documentoId + \"/v\" + numero + \".bin\";\n    }\n\n    /** Guarda el contenido en la referencia indicada, cifrado si hay clave configurada. */\n    @Override\n    public void guardar(String referencia, byte[] contenido) {\n        Path destino = resolver(referencia);\n        try {\n            Files.createDirectories(destino.getParent());\n            Files.write(destino, protector.cifrar(contenido),\n                    StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE);\n        } catch (IOException e) {\n            throw new IllegalStateException(\"No se pudo guardar el archivo\", e);\n        }\n    }\n\n    /** Lee el contenido de una referencia y lo descifra si corresponde. */\n    @Override\n    public byte[] leer(String referencia) {\n        try {\n            return protector.descifrar(Files.readAllBytes(resolver(referencia)));\n        } catch (IOException e) {\n            throw new IllegalStateException(\"No se pudo leer el archivo\", e);\n        }\n    }\n\n    /** Borra el archivo de una referencia. Si no existe, no hace nada. */\n    @Override\n    public void borrar(String referencia) {\n        try {\n            Files.deleteIfExists(resolver(referencia));\n        } catch (IOException e) {\n            throw new IllegalStateException(\"No se pudo borrar el archivo\", e);\n        }\n    }\n\n    /** Convierte una referencia en una ruta del disco, impidiendo salir del directorio base. */\n    private Path resolver(String referencia) {\n        Path p = raiz.resolve(referencia).normalize();\n        if (!p.startsWith(raiz)) {\n            throw new IllegalArgumentException(\"Referencia fuera del almacén\");\n        }\n        return p;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/documentos/infrastructure/indicadores/PublicadorIndicadoresVencimientos.java": "package com.mx.josesaid.develop.documentos.infrastructure.indicadores;\n\nimport java.math.BigDecimal;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport java.time.YearMonth;\nimport java.time.ZoneId;\nimport java.util.concurrent.TimeUnit;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.kafka.core.KafkaTemplate;\nimport org.springframework.scheduling.annotation.Scheduled;\nimport org.springframework.stereotype.Component;\nimport tools.jackson.databind.ObjectMapper;\n\n/**\n * Publica a reportes-ejecutivos-ms el indicador \"documentos por vencer en 30 días\" del área legal.\n *\n * <p>Cuenta los documentos no eliminados que vencen entre hoy y dentro de 30 días. Depende de la fecha\n * de hoy, así que solo publica el mes actual. Es una foto, no un evento: no pasa por el outbox; si un\n * envío falla, el siguiente ciclo lo corrige.\n */\n@Component\npublic class PublicadorIndicadoresVencimientos {\n\n    private static final Logger log = LoggerFactory.getLogger(PublicadorIndicadoresVencimientos.class);\n\n    /** Valor del enum Area de reportes-ejecutivos-ms. */\n    public static final String AREA = \"ADMINISTRACION_LEGAL\";\n    public static final String NOMBRE = \"documentos_por_vencer_30d\";\n\n    private static final ZoneId ZONA = ZoneId.of(\"America/Mexico_City\");\n\n    private static final String SQL_VENCIMIENTOS = \"\"\"\n            SELECT COUNT(*)::numeric\n            FROM documentos\n            WHERE eliminado = FALSE\n              AND vence_en BETWEEN ? AND ?\n            \"\"\";\n\n    private final JdbcTemplate jdbc;\n    private final KafkaTemplate<String, String> kafka;\n    private final ObjectMapper mapper;\n    private final Clock reloj;\n    private final String topico;\n\n    /** Recibe JDBC para los conteos, Kafka para publicar y el reloj. */\n    public PublicadorIndicadoresVencimientos(JdbcTemplate jdbc, KafkaTemplate<String, String> kafka,\n                                             ObjectMapper mapper, Clock reloj,\n                                             @Value(\"${indicadores.topico:indicadores-areas}\") String topico) {\n        this.jdbc = jdbc;\n        this.kafka = kafka;\n        this.mapper = mapper;\n        this.reloj = reloj;\n        this.topico = topico;\n    }\n\n    /** Publica en Kafka el conteo de documentos por vencer para que reportes-ejecutivos lo muestre. */\n    @Scheduled(fixedDelayString = \"${indicadores.intervalo-ms:3600000}\",\n            initialDelayString = \"${indicadores.inicio-ms:30000}\")\n    public void publicar() {\n        LocalDate hoy = LocalDate.now(reloj.withZone(ZONA));\n        BigDecimal valor = jdbc.queryForObject(SQL_VENCIMIENTOS, BigDecimal.class,\n                java.sql.Date.valueOf(hoy), java.sql.Date.valueOf(hoy.plusDays(30)));\n        String periodo = YearMonth.from(hoy).toString();\n        String payload = mapper.writeValueAsString(\n                new IndicadorEvento(AREA, NOMBRE, periodo, valor, Instant.now(reloj)));\n        try {\n            kafka.send(topico, AREA + \"|\" + NOMBRE + \"|\" + periodo, payload).get(10, TimeUnit.SECONDS);\n            log.info(\"Indicador publicado: {} {} {}\", AREA, NOMBRE, periodo);\n        } catch (InterruptedException ie) {\n            Thread.currentThread().interrupt();\n        } catch (Exception ex) {\n            log.warn(\"No se pudo publicar el indicador {} {}: {}\", NOMBRE, periodo, ex.getClass().getSimpleName());\n        }\n    }\n\n    /**\n     * Formato que espera reportes-ejecutivos-ms (ListenerIndicadores.IndicadorEvento).\n     *\n     * @param area componente de tipo {@code String}.\n     * @param nombre componente de tipo {@code String}.\n     * @param periodo componente de tipo {@code String}.\n     * @param valor componente de tipo {@code BigDecimal}.\n     * @param fuenteActualizadaUtc componente de tipo {@code Instant}.\n     */\n    public record IndicadorEvento(String area, String nombre, String periodo, BigDecimal valor,\n                                  Instant fuenteActualizadaUtc) {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/documentos/infrastructure/outbox/OutboxEntity.java": "package com.mx.josesaid.develop.documentos.infrastructure.outbox;\n\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.Table;\nimport java.time.Instant;\nimport java.util.UUID;\n\n/** Evento pendiente de publicar a Kafka. Se escribe en la misma transacción que el cambio de negocio. */\n@Entity\n@Table(name = \"outbox_eventos\")\npublic class OutboxEntity {\n\n    @Id\n    private UUID id;\n\n    @Column(nullable = false, length = 100)\n    private String tipo;\n\n    @Column(name = \"agregado_id\", nullable = false, length = 100)\n    private String agregadoId;\n\n    /** Sobre JSON completo: tipo, agregadoId y datos. */\n    @Column(nullable = false, columnDefinition = \"TEXT\")\n    private String payload;\n\n    @Column(name = \"creado_utc\", nullable = false)\n    private Instant creadoUtc;\n\n    @Column(name = \"publicado_utc\")\n    private Instant publicadoUtc;\n\n    @Column(nullable = false)\n    private int intentos;\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected OutboxEntity() {\n        // requerido por JPA\n    }\n\n    /** Crea un evento pendiente de publicar en el outbox. */\n    public OutboxEntity(UUID id, String tipo, String agregadoId, String payload, Instant creadoUtc) {\n        this.id = id;\n        this.tipo = tipo;\n        this.agregadoId = agregadoId;\n        this.payload = payload;\n        this.creadoUtc = creadoUtc;\n        this.intentos = 0;\n    }\n\n    /** Marca el evento como publicado en la fecha indicada. */\n    public void marcarPublicado(Instant ahora) {\n        this.publicadoUtc = ahora;\n    }\n\n    /** Suma un intento fallido de publicación. */\n    public void registrarIntentoFallido() {\n        this.intentos++;\n    }\n\n    /** Devuelve el identificador del evento. */\n    public UUID getId() { return id; }\n    /** Devuelve el tipo del evento. */\n    public String getTipo() { return tipo; }\n    /** Devuelve el identificador del agregado al que pertenece el evento. */\n    public String getAgregadoId() { return agregadoId; }\n    /** Devuelve el payload JSON del evento. */\n    public String getPayload() { return payload; }\n    /** Devuelve la fecha de creación en UTC. */\n    public Instant getCreadoUtc() { return creadoUtc; }\n    /** Devuelve la fecha de publicación en UTC, o nula si no se ha publicado. */\n    public Instant getPublicadoUtc() { return publicadoUtc; }\n    /** Devuelve el número de intentos fallidos. */\n    public int getIntentos() { return intentos; }\n}\n", "src/main/java/com/mx/josesaid/develop/documentos/infrastructure/outbox/OutboxJpaRepository.java": "package com.mx.josesaid.develop.documentos.infrastructure.outbox;\n\nimport java.util.List;\nimport java.util.UUID;\nimport org.springframework.data.jpa.repository.JpaRepository;\n\n/** Acceso a la tabla outbox con Spring Data JPA. */\npublic interface OutboxJpaRepository extends JpaRepository<OutboxEntity, UUID> {\n\n    /** Eventos pendientes, del más antiguo al más nuevo, en lotes de 100. */\n    List<OutboxEntity> findTop100ByPublicadoUtcIsNullOrderByCreadoUtcAsc();\n}\n", "src/main/java/com/mx/josesaid/develop/documentos/infrastructure/outbox/PublicadorEventosOutbox.java": "package com.mx.josesaid.develop.documentos.infrastructure.outbox;\n\nimport com.mx.josesaid.develop.documentos.application.EventoDominio;\nimport com.mx.josesaid.develop.documentos.application.PublicadorEventos;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.util.Map;\nimport java.util.UUID;\nimport org.springframework.stereotype.Component;\nimport tools.jackson.databind.ObjectMapper;\n\n/**\n * Implementación del patrón outbox: guarda el evento en la base de datos dentro de la\n * transacción de negocio. El envío a Kafka lo hace {@link RetransmisorOutbox}.\n */\n@Component\npublic class PublicadorEventosOutbox implements PublicadorEventos {\n\n    private final OutboxJpaRepository outbox;\n    private final ObjectMapper mapper;\n    private final Clock reloj;\n\n    /** Recibe el repositorio del outbox, el lector JSON y el reloj. */\n    public PublicadorEventosOutbox(OutboxJpaRepository outbox, ObjectMapper mapper, Clock reloj) {\n        this.outbox = outbox;\n        this.mapper = mapper;\n        this.reloj = reloj;\n    }\n\n    /** Guarda el evento en el outbox dentro de la misma transacción que el cambio de datos. */\n    @Override\n    public void publicar(EventoDominio evento) {\n        String sobre = mapper.writeValueAsString(Map.of(\n                \"tipo\", evento.tipo(),\n                \"agregadoId\", evento.agregadoId(),\n                \"datos\", evento.datos()));\n        outbox.save(new OutboxEntity(UUID.randomUUID(), evento.tipo(), evento.agregadoId(),\n                sobre, Instant.now(reloj)));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/documentos/infrastructure/outbox/RetransmisorOutbox.java": "package com.mx.josesaid.develop.documentos.infrastructure.outbox;\n\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.util.concurrent.TimeUnit;\nimport org.springframework.kafka.core.KafkaTemplate;\nimport org.springframework.scheduling.annotation.Scheduled;\nimport org.springframework.stereotype.Component;\nimport org.springframework.transaction.annotation.Transactional;\n\n/**\n * Envía a Kafka los eventos pendientes del outbox.\n *\n * <p>Se detiene en el primer fallo para conservar el orden de los eventos.\n * Un evento con error queda pendiente y se reintenta en el siguiente ciclo.\n */\n@Component\npublic class RetransmisorOutbox {\n\n    /** Tópico donde se publican los eventos de identidad. */\n    public static final String TOPICO = \"documentos.eventos\";\n\n    private final OutboxJpaRepository outbox;\n    private final KafkaTemplate<String, String> kafka;\n    private final Clock reloj;\n\n    /** Recibe el repositorio del outbox, el productor de Kafka y el reloj. */\n    public RetransmisorOutbox(OutboxJpaRepository outbox, KafkaTemplate<String, String> kafka, Clock reloj) {\n        this.outbox = outbox;\n        this.kafka = kafka;\n        this.reloj = reloj;\n    }\n\n    /** Envía a Kafka los eventos pendientes. Si el envío falla, deja el evento para el siguiente intento. */\n    @Scheduled(fixedDelayString = \"${documentos.outbox.intervalo-ms:5000}\")\n    @Transactional\n    public void transmitir() {\n        for (OutboxEntity evento : outbox.findTop100ByPublicadoUtcIsNullOrderByCreadoUtcAsc()) {\n            try {\n                kafka.send(TOPICO, evento.getAgregadoId(), evento.getPayload()).get(10, TimeUnit.SECONDS);\n                evento.marcarPublicado(Instant.now(reloj));\n            } catch (InterruptedException ie) {\n                Thread.currentThread().interrupt();\n                return;\n            } catch (Exception ex) {\n                evento.registrarIntentoFallido();\n                return;\n            }\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/documentos/infrastructure/persistence/DocumentoEntity.java": "package com.mx.josesaid.develop.documentos.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.documentos.domain.Documento;\nimport com.mx.josesaid.develop.documentos.domain.TipoDocumento;\nimport com.mx.josesaid.develop.documentos.domain.VersionDocumento;\nimport jakarta.persistence.CascadeType;\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.EnumType;\nimport jakarta.persistence.Enumerated;\nimport jakarta.persistence.FetchType;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.OneToMany;\nimport jakarta.persistence.OrderBy;\nimport jakarta.persistence.Table;\nimport jakarta.persistence.Version;\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.Set;\nimport java.util.UUID;\nimport java.util.stream.Collectors;\n\n/** Fila de la tabla de documentos. Guarda los datos del documento y su historial de versiones. */\n@Entity\n@Table(name = \"documentos\")\npublic class DocumentoEntity {\n\n    @Id\n    private UUID id;\n\n    @Enumerated(EnumType.STRING)\n    @Column(nullable = false, length = 20)\n    private TipoDocumento tipo;\n\n    @Column(nullable = false, length = 150)\n    private String titulo;\n\n    @Column(nullable = false, length = 100)\n    private String area;\n\n    @Column(name = \"vence_en\")\n    private LocalDate venceEn;\n\n    @Column(name = \"retencion_hasta\", nullable = false)\n    private LocalDate retencionHasta;\n\n    @Column(nullable = false)\n    private boolean eliminado;\n\n    @Column(name = \"motivo_eliminacion\", length = 300)\n    private String motivoEliminacion;\n\n    @Column(name = \"eliminado_utc\")\n    private Instant eliminadoUtc;\n\n    @Column(name = \"revision_retencion\", nullable = false)\n    private boolean revisionRetencion;\n\n    @Column(name = \"alerta_vencimiento_emitida\", nullable = false)\n    private boolean alertaVencimientoEmitida;\n\n    @Column(nullable = false)\n    private boolean purgado;\n\n    @Column(name = \"purgado_utc\")\n    private Instant purgadoUtc;\n\n    @Version\n    private Long version;\n\n    @OneToMany(mappedBy = \"documento\", cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.EAGER)\n    @OrderBy(\"numero ASC\")\n    private List<VersionEntity> versiones = new ArrayList<>();\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected DocumentoEntity() {\n    }\n\n    /** Crea una fila a partir de un documento del dominio. */\n    static DocumentoEntity nuevo(Documento d) {\n        DocumentoEntity e = new DocumentoEntity();\n        e.id = d.getId();\n        e.actualizar(d);\n        return e;\n    }\n\n    /** Actualiza campos y agrega solo las versiones nuevas: las existentes no se reescriben. */\n    void actualizar(Documento d) {\n        this.tipo = d.getTipo();\n        this.titulo = d.getTitulo();\n        this.area = d.getArea();\n        this.venceEn = d.getVenceEn();\n        this.retencionHasta = d.getRetencionHasta();\n        this.eliminado = d.isEliminado();\n        this.motivoEliminacion = d.getMotivoEliminacion();\n        this.eliminadoUtc = d.getEliminadoUtc();\n        this.revisionRetencion = d.isRevisionRetencion();\n        this.alertaVencimientoEmitida = d.isAlertaVencimientoEmitida();\n        this.purgado = d.isPurgado();\n        this.purgadoUtc = d.getPurgadoUtc();\n        Set<UUID> existentes = versiones.stream().map(VersionEntity::getId).collect(Collectors.toSet());\n        for (VersionDocumento v : d.getVersiones()) {\n            if (!existentes.contains(v.id())) {\n                versiones.add(new VersionEntity(this, v));\n            }\n        }\n    }\n\n    /** Convierte la fila en el objeto del dominio. */\n    Documento aDominio() {\n        return Documento.reconstruir(id, tipo, titulo, area, venceEn, retencionHasta,\n                versiones.stream().map(VersionEntity::aDominio).toList(),\n                eliminado, motivoEliminacion, eliminadoUtc, revisionRetencion, alertaVencimientoEmitida,\n                purgado, purgadoUtc);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/documentos/infrastructure/persistence/DocumentoJpaRepository.java": "package com.mx.josesaid.develop.documentos.infrastructure.persistence;\n\nimport java.time.LocalDate;\nimport java.util.List;\nimport java.util.UUID;\nimport org.springframework.data.jpa.repository.JpaRepository;\nimport org.springframework.data.jpa.repository.Query;\nimport org.springframework.data.repository.query.Param;\n\n/** Acceso a la tabla de documentos con Spring Data JPA. */\npublic interface DocumentoJpaRepository extends JpaRepository<DocumentoEntity, UUID> {\n\n    @Query(\"select d from DocumentoEntity d where d.eliminado = false and d.venceEn between :desde and :hasta\")\n    List<DocumentoEntity> buscarVencenEntre(@Param(\"desde\") LocalDate desde, @Param(\"hasta\") LocalDate hasta);\n\n    @Query(\"select d from DocumentoEntity d where d.eliminado = false and d.retencionHasta < :hoy \"\n            + \"and d.revisionRetencion = false\")\n    List<DocumentoEntity> buscarActivosConRetencionVencida(@Param(\"hoy\") LocalDate hoy);\n\n    /** Busca documentos cuyo título contiene el patrón indicado, con límite de resultados. */\n    @Query(\"select d from DocumentoEntity d where d.eliminado = false and lower(d.titulo) like :patron escape '!' \"\n            + \"order by d.titulo asc\")\n    List<DocumentoEntity> buscarPorTitulo(@Param(\"patron\") String patron,\n                                          org.springframework.data.domain.Pageable pageable);\n}\n", "src/main/java/com/mx/josesaid/develop/documentos/infrastructure/persistence/DocumentoRepositorioJpa.java": "package com.mx.josesaid.develop.documentos.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.documentos.domain.Documento;\nimport com.mx.josesaid.develop.documentos.domain.DocumentoRepositorio;\nimport java.time.LocalDate;\nimport java.util.List;\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.springframework.stereotype.Repository;\n\n/** Implementa el puerto de documentos con JPA. */\n@Repository\npublic class DocumentoRepositorioJpa implements DocumentoRepositorio {\n\n    private final DocumentoJpaRepository jpa;\n\n    /** Recibe el repositorio JPA de documentos. */\n    public DocumentoRepositorioJpa(DocumentoJpaRepository jpa) {\n        this.jpa = jpa;\n    }\n\n    /** Guarda un documento con sus versiones y devuelve la versión persistida. */\n    @Override\n    public Documento guardar(Documento documento) {\n        DocumentoEntity e = jpa.findById(documento.getId())\n                .map(existente -> {\n                    existente.actualizar(documento);\n                    return existente;\n                })\n                .orElseGet(() -> DocumentoEntity.nuevo(documento));\n        return jpa.save(e).aDominio();\n    }\n\n    /** Busca un documento por identificador. */\n    @Override\n    public Optional<Documento> buscarPorId(UUID id) {\n        return jpa.findById(id).map(DocumentoEntity::aDominio);\n    }\n\n    /** Lista los documentos cuyo vencimiento cae entre dos fechas. */\n    @Override\n    public List<Documento> buscarVencenEntre(LocalDate desde, LocalDate hasta) {\n        return jpa.buscarVencenEntre(desde, hasta).stream().map(DocumentoEntity::aDominio).toList();\n    }\n\n    /** Busca documentos por título, con límite de resultados. */\n    @Override\n    public List<Documento> buscarPorTitulo(String texto, int limite) {\n        String escapado = texto.toLowerCase().replace(\"!\", \"!!\").replace(\"%\", \"!%\").replace(\"_\", \"!_\");\n        return jpa.buscarPorTitulo(\"%\" + escapado + \"%\", org.springframework.data.domain.PageRequest.of(0, limite))\n                .stream().map(DocumentoEntity::aDominio).toList();\n    }\n\n    /** Lista documentos activos cuya retención ya venció, para revisarlos. */\n    @Override\n    public List<Documento> buscarActivosConRetencionVencida(LocalDate hoy) {\n        return jpa.buscarActivosConRetencionVencida(hoy).stream().map(DocumentoEntity::aDominio).toList();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/documentos/infrastructure/persistence/VersionEntity.java": "package com.mx.josesaid.develop.documentos.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.documentos.domain.VersionDocumento;\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.FetchType;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.JoinColumn;\nimport jakarta.persistence.ManyToOne;\nimport jakarta.persistence.Table;\nimport java.time.Instant;\nimport java.util.UUID;\n\n/** Fila de una versión del documento: número, huella y referencia de almacenamiento. */\n@Entity\n@Table(name = \"versiones_documento\")\npublic class VersionEntity {\n\n    @Id\n    private UUID id;\n\n    /** Dueño de la relación. updatable=false: la clave foránea se escribe solo al insertar, nunca después. */\n    @ManyToOne(fetch = FetchType.LAZY, optional = false)\n    @JoinColumn(name = \"documento_id\", nullable = false, updatable = false)\n    private DocumentoEntity documento;\n\n    @Column(nullable = false)\n    private int numero;\n\n    @Column(name = \"hash_sha256\", nullable = false, length = 64)\n    private String hashSha256;\n\n    @Column(name = \"almacenamiento_ref\", nullable = false, length = 300)\n    private String almacenamientoRef;\n\n    @Column(name = \"creado_utc\", nullable = false)\n    private Instant creadoUtc;\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected VersionEntity() {\n    }\n\n    VersionEntity(DocumentoEntity documento, VersionDocumento v) {\n        this.documento = documento;\n        this.id = v.id();\n        this.numero = v.numero();\n        this.hashSha256 = v.hashSha256();\n        this.almacenamientoRef = v.almacenamientoRef();\n        this.creadoUtc = v.creadoUtc();\n    }\n\n    /** Devuelve el identificador de la versión. */\n    UUID getId() {\n        return id;\n    }\n\n    /** Convierte la fila en la versión del dominio. */\n    VersionDocumento aDominio() {\n        return new VersionDocumento(id, numero, hashSha256, almacenamientoRef, creadoUtc);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/documentos/infrastructure/programacion/TareasDocumentales.java": "package com.mx.josesaid.develop.documentos.infrastructure.programacion;\n\nimport com.mx.josesaid.develop.documentos.application.DocumentosService;\nimport org.springframework.scheduling.annotation.Scheduled;\nimport org.springframework.stereotype.Component;\n\n/** Dispara cada día las alertas de vencimiento y las revisiones de retención. Horario configurable. */\n@Component\npublic class TareasDocumentales {\n\n    private final DocumentosService servicio;\n\n    /** Recibe el servicio de documentos para las tareas programadas. */\n    public TareasDocumentales(DocumentosService servicio) {\n        this.servicio = servicio;\n    }\n\n    /** Tarea programada: procesa los vencimientos y las retenciones de los documentos. */\n    @Scheduled(cron = \"${documentos.alertas.cron:0 0 7 * * *}\")\n    public void procesarVencimientos() {\n        servicio.procesarVencimientos();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/documentos/infrastructure/seguridad/ProtectorArchivos.java": "package com.mx.josesaid.develop.documentos.infrastructure.seguridad;\n\nimport java.nio.ByteBuffer;\nimport java.security.GeneralSecurityException;\nimport java.security.SecureRandom;\nimport java.util.Base64;\nimport javax.crypto.Cipher;\nimport javax.crypto.spec.GCMParameterSpec;\nimport javax.crypto.spec.SecretKeySpec;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.stereotype.Component;\n\n/**\n * Cifrado en reposo de archivos con AES-256-GCM. Formato guardado: IV (12 bytes) + texto cifrado con etiqueta.\n * La clave viene de DOCUMENTOS_CIFRADO_CLAVE (base64, 32 bytes). Sin ella el servicio no arranca.\n */\n@Component\npublic class ProtectorArchivos {\n\n    private static final int IV_BYTES = 12;\n    private static final int TAG_BITS = 128;\n\n    private final SecretKeySpec clave;\n    private final SecureRandom aleatorio = new SecureRandom();\n\n    /** Recibe la clave de cifrado en Base64, configurada en documentos.cifrado.clave. Sin clave, los archivos se guardan sin cifrar y se registra la advertencia. */\n    public ProtectorArchivos(@Value(\"${documentos.cifrado.clave:}\") String claveBase64) {\n        byte[] bytes;\n        try {\n            bytes = Base64.getDecoder().decode(claveBase64);\n        } catch (IllegalArgumentException e) {\n            throw new IllegalStateException(\"documentos.cifrado.clave no es base64 válido\", e);\n        }\n        if (bytes.length != 32) {\n            throw new IllegalStateException(\"documentos.cifrado.clave debe ser AES-256 (32 bytes en base64)\");\n        }\n        this.clave = new SecretKeySpec(bytes, \"AES\");\n    }\n\n    /** Cifra el contenido de un archivo antes de guardarlo. */\n    public byte[] cifrar(byte[] claro) {\n        byte[] iv = new byte[IV_BYTES];\n        aleatorio.nextBytes(iv);\n        try {\n            Cipher cipher = Cipher.getInstance(\"AES/GCM/NoPadding\");\n            cipher.init(Cipher.ENCRYPT_MODE, clave, new GCMParameterSpec(TAG_BITS, iv));\n            byte[] cifrado = cipher.doFinal(claro);\n            return ByteBuffer.allocate(iv.length + cifrado.length).put(iv).put(cifrado).array();\n        } catch (GeneralSecurityException e) {\n            throw new IllegalStateException(\"No se pudo cifrar el archivo\", e);\n        }\n    }\n\n    /** Descifra el contenido de un archivo leído del disco. */\n    public byte[] descifrar(byte[] cifrado) {\n        if (cifrado.length <= IV_BYTES) {\n            throw new IllegalStateException(\"Archivo cifrado inválido\");\n        }\n        ByteBuffer buffer = ByteBuffer.wrap(cifrado);\n        byte[] iv = new byte[IV_BYTES];\n        buffer.get(iv);\n        byte[] cuerpo = new byte[buffer.remaining()];\n        buffer.get(cuerpo);\n        try {\n            Cipher cipher = Cipher.getInstance(\"AES/GCM/NoPadding\");\n            cipher.init(Cipher.DECRYPT_MODE, clave, new GCMParameterSpec(TAG_BITS, iv));\n            return cipher.doFinal(cuerpo);\n        } catch (GeneralSecurityException e) {\n            throw new IllegalStateException(\"El archivo no pasó la verificación de integridad\", e);\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/documentos/seguridad/EntradaNoAutorizada.java": "package com.mx.josesaid.develop.documentos.seguridad;\n\nimport jakarta.servlet.http.HttpServletRequest;\nimport jakarta.servlet.http.HttpServletResponse;\nimport java.io.IOException;\nimport org.springframework.security.core.AuthenticationException;\nimport org.springframework.security.oauth2.jwt.JwtValidationException;\nimport org.springframework.security.web.AuthenticationEntryPoint;\n\n/**\n * Responde 401 y deja el motivo en WWW-Authenticate. Solo expone el motivo de sesión cerrada;\n * cualquier otro fallo de validación se reporta como \"Invalid token\", sin detalles de decodificación.\n * Spring puede llamar dos veces al punto de entrada en la misma petición: el primer motivo se conserva.\n */\npublic class EntradaNoAutorizada implements AuthenticationEntryPoint {\n\n    private static final String MOTIVO_GENERICO = \"Invalid token\";\n    private static final String ATRIBUTO = EntradaNoAutorizada.class.getName() + \".motivo\";\n\n    /** Responde 401 cuando la petición no trae un token válido. */\n    @Override\n    public void commence(HttpServletRequest request, HttpServletResponse response, AuthenticationException ex)\n            throws IOException {\n        String previo = (String) request.getAttribute(ATRIBUTO);\n        String motivo = previo != null ? previo : motivo(ex);\n        request.setAttribute(ATRIBUTO, motivo);\n        response.setHeader(\"WWW-Authenticate\",\n                \"Bearer error=\\\"invalid_token\\\", error_description=\\\"\" + motivo + \"\\\"\");\n        response.sendError(HttpServletResponse.SC_UNAUTHORIZED);\n    }\n\n    /** Explica por qué se rechazó el token, en texto breve para el log. */\n    private static String motivo(Throwable ex) {\n        for (Throwable t = ex; t != null; t = t.getCause()) {\n            if (t instanceof JwtValidationException jve && jve.getErrors().stream()\n                    .anyMatch(e -> ValidadorRevocacion.MOTIVO.equals(e.getDescription()))) {\n                return ValidadorRevocacion.MOTIVO;\n            }\n        }\n        return MOTIVO_GENERICO;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/documentos/seguridad/ListenerRevocaciones.java": "package com.mx.josesaid.develop.documentos.seguridad;\n\nimport java.time.Instant;\nimport java.util.Map;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.kafka.annotation.KafkaListener;\nimport org.springframework.stereotype.Component;\nimport tools.jackson.databind.ObjectMapper;\n\n/**\n * Recibe de usuarios-accesos-ms los cierres de sesión y los aplica a la copia local de revocaciones.\n * Los eventos ajenos se ignoran; un mensaje inválido se registra y se descarta.\n * Cada arranque usa un grupo de consumo nuevo y lee el topic desde el inicio: así reconstruye las\n * revocaciones vigentes. Los eventos vencidos los descarta RevocacionSesiones.\n */\n@Component\npublic class ListenerRevocaciones {\n\n    private static final Logger log = LoggerFactory.getLogger(ListenerRevocaciones.class);\n\n    private final RevocacionSesiones revocaciones;\n    private final ObjectMapper mapper;\n\n    /** Recibe la copia local de revocaciones y el lector JSON. */\n    public ListenerRevocaciones(RevocacionSesiones revocaciones, ObjectMapper mapper) {\n        this.revocaciones = revocaciones;\n        this.mapper = mapper;\n    }\n\n    /** Aplica al instante un evento de cierre de sesión recibido por Kafka. */\n    @KafkaListener(topics = \"${seguridad.revocaciones.topico:usuarios-accesos.eventos}\",\n                   groupId = \"documentos-cumplimiento-ms-revocaciones-#{T(java.util.UUID).randomUUID()}\",\n                   properties = \"auto.offset.reset=earliest\")\n    public void recibir(String mensaje) {\n        try {\n            Sobre sobre = mapper.readValue(mensaje, Sobre.class);\n            String tipo = sobre.tipo();\n            if (!\"sesion-cerrada\".equals(tipo) && !\"sesiones-usuario-cerradas\".equals(tipo)) {\n                return;\n            }\n            Map<String, Object> datos = sobre.datos() == null ? Map.of() : sobre.datos();\n            Instant ocurridoEn = Instant.parse(String.valueOf(datos.get(\"ocurridoEn\")));\n            if (\"sesion-cerrada\".equals(tipo)) {\n                revocaciones.revocarSesion(String.valueOf(datos.get(\"sid\")), ocurridoEn);\n            } else {\n                revocaciones.revocarUsuario(String.valueOf(datos.get(\"usuarioId\")), ocurridoEn);\n            }\n        } catch (RuntimeException e) {\n            log.warn(\"Evento de revocación descartado: {}\", e.getClass().getSimpleName());\n        }\n    }\n\n    /**\n     * Sobre que publica usuarios-accesos-ms por el outbox.\n     *\n     * @param tipo componente de tipo {@code String}.\n     * @param agregadoId componente de tipo {@code String}.\n     * @param datos componente de tipo {@code Map<String, Object>}.\n     */\n    public record Sobre(String tipo, String agregadoId, Map<String, Object> datos) {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/documentos/seguridad/RevocacionSesiones.java": "package com.mx.josesaid.develop.documentos.seguridad;\n\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.Map;\nimport java.util.concurrent.ConcurrentHashMap;\nimport org.springframework.stereotype.Component;\n\n/**\n * Sesiones cerradas, recordadas en memoria solo mientras pueda haber tokens vigentes.\n * Cada servicio mantiene su copia: un reinicio la vacía, y los tokens revocados expiran igual en 15 minutos.\n */\n@Component\npublic class RevocacionSesiones {\n\n    /** Vida del access token (15 min) más un margen. Pasado ese tiempo, ningún token revocado sigue vigente. */\n    public static final Duration VIDA = Duration.ofMinutes(20);\n\n    private final Map<String, Instant> sesiones = new ConcurrentHashMap<>();\n    private final Map<String, Instant> usuarios = new ConcurrentHashMap<>();\n\n    /** Revoca una sesión (su sid) cerrada en el instante dado. */\n    public void revocarSesion(String sid, Instant ocurridoEn) {\n        if (sid == null || vencido(ocurridoEn)) {\n            return;\n        }\n        sesiones.put(sid, ocurridoEn);\n    }\n\n    /** Revoca los tokens del usuario emitidos antes del instante dado. */\n    public void revocarUsuario(String usuarioId, Instant ocurridoEn) {\n        if (usuarioId == null || vencido(ocurridoEn)) {\n            return;\n        }\n        usuarios.merge(usuarioId, ocurridoEn, (actual, nuevoValor) -> nuevoValor.isAfter(actual) ? nuevoValor : actual);\n    }\n\n    /** true si un token con ese sid, usuario y fecha de emisión ya no debe aceptarse. */\n    public boolean revocado(String sid, String usuarioId, Instant emitidoEn) {\n        limpiar();\n        if (sid != null && sesiones.containsKey(sid)) {\n            return true;\n        }\n        Instant cerradoEn = usuarioId == null ? null : usuarios.get(usuarioId);\n        return cerradoEn != null && emitidoEn != null && emitidoEn.isBefore(cerradoEn);\n    }\n\n    /** Indica si un registro de revocación ya venció y puede descartarse. */\n    private static boolean vencido(Instant ocurridoEn) {\n        return ocurridoEn == null || ocurridoEn.plus(VIDA).isBefore(Instant.now());\n    }\n\n    /** Elimina las revocaciones vencidas para no crecer sin límite. */\n    private void limpiar() {\n        Instant limite = Instant.now().minus(VIDA);\n        sesiones.values().removeIf(t -> t.isBefore(limite));\n        usuarios.values().removeIf(t -> t.isBefore(limite));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/documentos/seguridad/ValidadorRevocacion.java": "package com.mx.josesaid.develop.documentos.seguridad;\n\nimport org.springframework.security.oauth2.core.OAuth2Error;\nimport org.springframework.security.oauth2.core.OAuth2TokenValidator;\nimport org.springframework.security.oauth2.core.OAuth2TokenValidatorResult;\nimport org.springframework.security.oauth2.jwt.Jwt;\n\n/** Rechaza los tokens de sesiones cerradas. Se combina con la validación estándar de firma y vencimiento. */\npublic class ValidadorRevocacion implements OAuth2TokenValidator<Jwt> {\n\n    /** Motivo que se devuelve al cliente cuando la sesión fue cerrada. */\n    public static final String MOTIVO = \"La sesion fue cerrada\";\n\n    private static final OAuth2Error REVOCADO = new OAuth2Error(\"invalid_token\", MOTIVO, null);\n\n    private final RevocacionSesiones revocaciones;\n\n    /** Recibe la copia local de revocaciones. */\n    public ValidadorRevocacion(RevocacionSesiones revocaciones) {\n        this.revocaciones = revocaciones;\n    }\n\n    /** Rechaza el JWT si su sesión o su usuario fueron revocados, aunque la firma y el vencimiento sean válidos. */\n    @Override\n    public OAuth2TokenValidatorResult validate(Jwt jwt) {\n        boolean revocado = revocaciones.revocado(jwt.getClaimAsString(\"sid\"), jwt.getSubject(), jwt.getIssuedAt());\n        return revocado ? OAuth2TokenValidatorResult.failure(REVOCADO) : OAuth2TokenValidatorResult.success();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/documentos/api/DocumentosControladorAutorizacionTest.java": "package com.mx.josesaid.develop.documentos.api;\n\nimport static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.multipart;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;\n\nimport com.mx.josesaid.develop.documentos.application.DocumentosService;\nimport com.mx.josesaid.develop.documentos.config.SeguridadConfig;\nimport java.util.List;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.context.TestConfiguration;\nimport org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;\nimport org.springframework.context.annotation.Import;\nimport org.springframework.http.MediaType;\nimport org.springframework.mock.web.MockMultipartFile;\nimport org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;\nimport org.springframework.security.core.GrantedAuthority;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.security.oauth2.jwt.JwtDecoder;\nimport org.springframework.test.context.bean.override.mockito.MockitoBean;\nimport org.springframework.test.web.servlet.MockMvc;\nimport org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder;\n\n/**\n * Matriz de autorización de DocumentosControlador.\n * Un rol permitido no debe recibir 401 ni 403; un rol no permitido debe recibir 403.\n * Las escrituras usan cuerpos y partes multipart válidos.\n */\n@WebMvcTest(DocumentosControlador.class)\n@Import({SeguridadConfig.class, DocumentosControladorAutorizacionTest.Configuracion.class})\nclass DocumentosControladorAutorizacionTest {\n\n    private static final String SUJETO = \"6f1c2e7a-9a3b-4c1d-8e2f-1a2b3c4d5e6f\";\n    private static final String ID = \"11111111-2222-3333-4444-555555555555\";\n    private static final String DATOS = \"{\\\"tipo\\\":\\\"CONTRATO\\\",\\\"titulo\\\":\\\"Contrato marco\\\",\\\"area\\\":\\\"Jurídico\\\",\\\"venceEn\\\":null}\";\n\n    @TestConfiguration\n    @EnableWebSecurity\n    static class Configuracion {\n    }\n\n    @Autowired\n    private MockMvc mvc;\n\n    @MockitoBean\n    private DocumentosService servicio;\n\n    @MockitoBean\n    private JwtDecoder jwtDecoder;\n\n    @SuppressWarnings(\"unchecked\")\n    private <T extends MockHttpServletRequestBuilder> T peticion(T base, String rol) {\n        List<GrantedAuthority> autoridades = rol.isEmpty() ? List.of()\n                : List.of(new SimpleGrantedAuthority(\"ROLE_\" + rol));\n        return (T) base.with(jwt().jwt(j -> j.subject(SUJETO)).authorities(autoridades));\n    }\n\n    private MockHttpServletRequestBuilder lectura(String ruta, String rol) {\n        return peticion(get(ruta), rol);\n    }\n\n    private MockHttpServletRequestBuilder json(String ruta, String cuerpo, String rol) {\n        var base = post(ruta).contentType(MediaType.APPLICATION_JSON);\n        if (cuerpo != null) {\n            base = base.content(cuerpo);\n        }\n        return peticion(base, rol);\n    }\n\n    private org.springframework.test.web.servlet.RequestBuilder crear(String rol) {\n        var datos = new MockMultipartFile(\"datos\", \"datos.json\", MediaType.APPLICATION_JSON_VALUE, DATOS.getBytes());\n        var archivo = new MockMultipartFile(\"archivo\", \"contrato.pdf\", \"application/pdf\", new byte[]{1, 2, 3});\n        return multipart(\"/v1/documentos\").file(datos).file(archivo).with(autenticado(rol));\n    }\n\n    private org.springframework.test.web.servlet.RequestBuilder version(String rol) {\n        var archivo = new MockMultipartFile(\"archivo\", \"v2.pdf\", \"application/pdf\", new byte[]{4, 5, 6});\n        return multipart(\"/v1/documentos/\" + ID + \"/versiones\").file(archivo).with(autenticado(rol));\n    }\n\n    private org.springframework.test.web.servlet.request.RequestPostProcessor autenticado(String rol) {\n        List<GrantedAuthority> autoridades = rol.isEmpty() ? List.of()\n                : List.of(new SimpleGrantedAuthority(\"ROLE_\" + rol));\n        return jwt().jwt(j -> j.subject(SUJETO)).authorities(autoridades);\n    }\n\n    private void permitido(org.springframework.test.web.servlet.RequestBuilder req, String descripcion, String rol) throws Exception {\n        int codigo;\n        try {\n            codigo = mvc.perform(req).andReturn().getResponse().getStatus();\n        } catch (jakarta.servlet.ServletException e) {\n            codigo = 200; // llegó al controlador: el rol fue aceptado\n        }\n        org.assertj.core.api.Assertions.assertThat(codigo)\n                .as(\"%s debería estar permitido para %s\", descripcion, rol)\n                .isNotIn(401, 403);\n    }\n\n    private void denegado(org.springframework.test.web.servlet.RequestBuilder req) throws Exception {\n        mvc.perform(req).andExpect(status().isForbidden());\n    }\n\n    @Test\n    void crearDocumento() throws Exception {\n        permitido(crear(\"LEGAL\"), \"POST /v1/documentos\", \"LEGAL\");\n        denegado(crear(\"DIRECCION\"));\n        denegado(crear(\"VENTAS\"));\n    }\n\n    @Test\n    void agregarVersion() throws Exception {\n        permitido(version(\"LEGAL\"), \"POST versiones\", \"LEGAL\");\n        denegado(version(\"DIRECCION\"));\n    }\n\n    @Test\n    void obtenerDocumento() throws Exception {\n        String ruta = \"/v1/documentos/\" + ID;\n        permitido(lectura(ruta, \"LEGAL\"), \"GET documento\", \"LEGAL\");\n        permitido(lectura(ruta, \"DIRECCION\"), \"GET documento\", \"DIRECCION\");\n        denegado(lectura(ruta, \"VENTAS\"));\n    }\n\n    @Test\n    void descargarVersion() throws Exception {\n        String ruta = \"/v1/documentos/\" + ID + \"/versiones/1/descarga\";\n        permitido(lectura(ruta, \"LEGAL\"), \"GET descarga\", \"LEGAL\");\n        denegado(lectura(ruta, \"DIRECCION\"));\n    }\n\n    @Test\n    void buscarPorTitulo() throws Exception {\n        String ruta = \"/v1/documentos?titulo=contrato\";\n        permitido(lectura(ruta, \"LEGAL\"), \"GET buscar\", \"LEGAL\");\n        permitido(lectura(ruta, \"DIRECCION\"), \"GET buscar\", \"DIRECCION\");\n        denegado(lectura(ruta, \"VENTAS\"));\n    }\n\n    @Test\n    void porVencer() throws Exception {\n        String ruta = \"/v1/documentos/por-vencer?dias=30\";\n        permitido(lectura(ruta, \"LEGAL\"), \"GET por-vencer\", \"LEGAL\");\n        permitido(lectura(ruta, \"DIRECCION\"), \"GET por-vencer\", \"DIRECCION\");\n        denegado(lectura(ruta, \"VENTAS\"));\n    }\n\n    @Test\n    void eliminarDocumento() throws Exception {\n        String ruta = \"/v1/documentos/\" + ID + \"/eliminacion\";\n        String cuerpo = \"{\\\"motivo\\\":\\\"Vencido\\\"}\";\n        permitido(json(ruta, cuerpo, \"LEGAL\"), \"POST eliminacion\", \"LEGAL\");\n        denegado(json(ruta, cuerpo, \"DIRECCION\"));\n    }\n\n    @Test\n    void purgarDocumento() throws Exception {\n        String ruta = \"/v1/documentos/\" + ID + \"/purga\";\n        String cuerpo = \"{\\\"confirmacion\\\":\\\"\" + ID + \"\\\"}\";\n        permitido(json(ruta, cuerpo, \"LEGAL\"), \"POST purga\", \"LEGAL\");\n        denegado(json(ruta, cuerpo, \"DIRECCION\"));\n    }\n\n    @Test\n    void catalogoTiposAbiertoAAutenticados() throws Exception {\n        String ruta = \"/v1/catalogos/tipos-documento\";\n        permitido(lectura(ruta, \"VENTAS\"), \"GET catálogo\", \"VENTAS\");\n        permitido(lectura(ruta, \"LEGAL\"), \"GET catálogo\", \"LEGAL\");\n    }\n\n    @Test\n    void sinRolNoHayAccesoAProtegidos() throws Exception {\n        denegado(lectura(\"/v1/documentos/\" + ID, \"\"));\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/documentos/api/DocumentosControladorValidacionTest.java": "package com.mx.josesaid.develop.documentos.api;\n\nimport static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;\n\nimport com.mx.josesaid.develop.documentos.application.DocumentosService;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.context.TestConfiguration;\nimport org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;\nimport org.springframework.context.annotation.Import;\nimport org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.security.oauth2.jwt.JwtDecoder;\nimport org.springframework.test.context.bean.override.mockito.MockitoBean;\nimport org.springframework.test.web.servlet.MockMvc;\n\n@WebMvcTest(DocumentosControlador.class)\n@Import(DocumentosControladorValidacionTest.Configuracion.class)\nclass DocumentosControladorValidacionTest {\n\n    private static final String SUJETO = \"6f1c2e7a-9a3b-4c1d-8e2f-1a2b3c4d5e6f\";\n\n    @TestConfiguration\n    @EnableWebSecurity\n    static class Configuracion {\n    }\n\n    @Autowired\n    private MockMvc mvc;\n\n    @MockitoBean\n    private DocumentosService servicio;\n\n    @MockitoBean\n    private JwtDecoder jwtDecoder;\n\n    @Test\n    void parametroDemasiadoLargoDa400() throws Exception {\n        mvc.perform(get(\"/v1/documentos\").param(\"titulo\", \"A\".repeat(201))\n                        .with(jwt().jwt(j -> j.subject(SUJETO))\n                                .authorities(new SimpleGrantedAuthority(\"ROLE_LEGAL\"))))\n                .andExpect(status().isBadRequest());\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/documentos/api/DocumentosIT.java": "package com.mx.josesaid.develop.documentos.api;\n\nimport static org.hamcrest.Matchers.hasItem;\nimport static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.multipart;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.content;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;\n\nimport com.jayway.jsonpath.JsonPath;\nimport java.nio.charset.StandardCharsets;\nimport java.time.LocalDate;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.context.SpringBootTest;\nimport org.springframework.boot.testcontainers.service.connection.ServiceConnection;\nimport org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;\nimport org.springframework.mock.web.MockMultipartFile;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.test.web.servlet.MockMvc;\nimport org.springframework.test.web.servlet.MvcResult;\nimport org.springframework.test.web.servlet.request.RequestPostProcessor;\nimport org.testcontainers.junit.jupiter.Container;\nimport org.testcontainers.junit.jupiter.Testcontainers;\nimport org.testcontainers.kafka.KafkaContainer;\nimport org.testcontainers.postgresql.PostgreSQLContainer;\n\n/** Integración con PostgreSQL, Kafka y almacenamiento cifrado reales (Testcontainers). Requiere Docker. */\n@SpringBootTest(properties = {\n        \"documentos.jwt.jwks-uri=http://localhost:9/.well-known/jwks.json\",\n        \"documentos.cifrado.clave=MDEyMzQ1Njc4OWFiY2RlZjAxMjM0NTY3ODlhYmNkZWY=\",\n        \"documentos.almacen.directorio=${java.io.tmpdir}/documentos-it-${random.uuid}\"})\n@AutoConfigureMockMvc\n@Testcontainers\nclass DocumentosIT {\n\n    @Container\n    @ServiceConnection\n    static PostgreSQLContainer postgres = new PostgreSQLContainer(\"postgres:17-alpine\");\n\n    @Container\n    @ServiceConnection\n    static KafkaContainer kafka = new KafkaContainer(\"apache/kafka:4.0.0\");\n\n    @Autowired\n    private MockMvc mvc;\n\n    @Test\n    void versionesDescargaYRetencionFuncionanExtremoAExtremo() throws Exception {\n        String datos = \"{\\\"tipo\\\":\\\"CONTRATO\\\",\\\"titulo\\\":\\\"Contrato marco\\\",\\\"area\\\":\\\"Administración y legal\\\"}\";\n        MvcResult creado = mvc.perform(multipart(\"/v1/documentos\")\n                        .file(archivo(\"contrato v1\")).file(parteDatos(datos)).with(rol(\"LEGAL\")))\n                .andExpect(status().isCreated())\n                .andExpect(jsonPath(\"$.versionActual\").value(1))\n                .andReturn();\n        String id = JsonPath.read(creado.getResponse().getContentAsString(), \"$.id\");\n\n        mvc.perform(multipart(\"/v1/documentos/\" + id + \"/versiones\")\n                        .file(archivo(\"contrato v2\")).with(rol(\"LEGAL\")))\n                .andExpect(status().isCreated())\n                .andExpect(jsonPath(\"$.versionActual\").value(2));\n\n        // Mismo contenido que la versión actual: no crea versión\n        mvc.perform(multipart(\"/v1/documentos/\" + id + \"/versiones\")\n                        .file(archivo(\"contrato v2\")).with(rol(\"LEGAL\")))\n                .andExpect(status().isConflict());\n\n        mvc.perform(get(\"/v1/documentos/\" + id + \"/versiones/1/descarga\").with(rol(\"LEGAL\")))\n                .andExpect(status().isOk())\n                .andExpect(content().bytes(\"contrato v1\".getBytes(StandardCharsets.UTF_8)));\n\n        // Dentro de la retención no se elimina\n        mvc.perform(post(\"/v1/documentos/\" + id + \"/eliminacion\").with(rol(\"LEGAL\"))\n                        .contentType(\"application/json\").content(\"{\\\"motivo\\\":\\\"Prueba\\\"}\"))\n                .andExpect(status().isConflict());\n    }\n\n    @Test\n    void permisosPorVencerYRolesSeAplican() throws Exception {\n        String permiso = \"\"\"\n                {\"tipo\":\"PERMISO\",\"titulo\":\"Permiso ambiental\",\"area\":\"Operaciones\",\"venceEn\":\"%s\"}\n                \"\"\".formatted(LocalDate.now().plusDays(5));\n\n        // DIRECCION solo consulta: no puede cargar\n        mvc.perform(multipart(\"/v1/documentos\").file(archivo(\"permiso\")).file(parteDatos(permiso))\n                        .with(rol(\"DIRECCION\")))\n                .andExpect(status().isForbidden());\n\n        mvc.perform(multipart(\"/v1/documentos\").file(archivo(\"permiso\")).file(parteDatos(permiso))\n                        .with(rol(\"LEGAL\")))\n                .andExpect(status().isCreated());\n\n        mvc.perform(get(\"/v1/documentos/por-vencer?dias=10\").with(rol(\"DIRECCION\")))\n                .andExpect(status().isOk())\n                .andExpect(jsonPath(\"$[*].titulo\").value(hasItem(\"Permiso ambiental\")));\n\n        mvc.perform(get(\"/v1/documentos/por-vencer?dias=-1\").with(rol(\"LEGAL\")))\n                .andExpect(status().isBadRequest());\n    }\n\n    @Test\n    void purgaSinEliminacionPreviaEsConflictoYSoloLegalPuedePurgar() throws Exception {\n        String datos = \"{\\\"tipo\\\":\\\"REGISTRO_LEGAL\\\",\\\"titulo\\\":\\\"Acta constitutiva\\\",\\\"area\\\":\\\"Legal\\\"}\";\n        MvcResult creado = mvc.perform(multipart(\"/v1/documentos\")\n                        .file(archivo(\"acta\")).file(parteDatos(datos)).with(rol(\"LEGAL\")))\n                .andExpect(status().isCreated())\n                .andReturn();\n        String id = JsonPath.read(creado.getResponse().getContentAsString(), \"$.id\");\n        String cuerpo = \"{\\\"confirmacion\\\":\\\"\" + id + \"\\\"}\";\n\n        mvc.perform(post(\"/v1/documentos/\" + id + \"/purga\").with(rol(\"DIRECCION\"))\n                        .contentType(\"application/json\").content(cuerpo))\n                .andExpect(status().isForbidden());\n\n        mvc.perform(post(\"/v1/documentos/\" + id + \"/purga\").with(rol(\"LEGAL\"))\n                        .contentType(\"application/json\").content(cuerpo))\n                .andExpect(status().isConflict());\n    }\n\n    private static MockMultipartFile archivo(String contenido) {\n        return new MockMultipartFile(\"archivo\", \"documento.pdf\", \"application/pdf\",\n                contenido.getBytes(StandardCharsets.UTF_8));\n    }\n\n    private static MockMultipartFile parteDatos(String json) {\n        return new MockMultipartFile(\"datos\", \"\", \"application/json\", json.getBytes(StandardCharsets.UTF_8));\n    }\n\n    private static RequestPostProcessor rol(String rol) {\n        return jwt().authorities(new SimpleGrantedAuthority(\"ROLE_\" + rol));\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/documentos/application/DocumentosBuscarTituloTest.java": "package com.mx.josesaid.develop.documentos.application;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\nimport static org.mockito.ArgumentMatchers.eq;\nimport static org.mockito.Mockito.mock;\nimport static org.mockito.Mockito.never;\nimport static org.mockito.Mockito.verify;\nimport static org.mockito.Mockito.when;\n\nimport com.mx.josesaid.develop.documentos.domain.Documento;\nimport com.mx.josesaid.develop.documentos.domain.DocumentoRepositorio;\nimport com.mx.josesaid.develop.documentos.domain.SolicitudInvalidaException;\nimport io.micrometer.core.instrument.simple.SimpleMeterRegistry;\nimport java.time.Clock;\nimport java.util.List;\nimport org.junit.jupiter.api.Test;\n\nclass DocumentosBuscarTituloTest {\n\n    @Test\n    void textoCortoSeRechazaSinConsultar() {\n        DocumentoRepositorio documentos = mock(DocumentoRepositorio.class);\n        DocumentosService servicio = servicio(documentos);\n\n        assertThatThrownBy(() -> servicio.buscarPorTitulo(\"ab\"))\n                .isInstanceOf(SolicitudInvalidaException.class);\n        verify(documentos, never()).buscarPorTitulo(org.mockito.ArgumentMatchers.anyString(),\n                org.mockito.ArgumentMatchers.anyInt());\n    }\n\n    @Test\n    void recortaElTextoYPideHastaQuince() {\n        DocumentoRepositorio documentos = mock(DocumentoRepositorio.class);\n        Documento doc = mock(Documento.class);\n        when(documentos.buscarPorTitulo(eq(\"contrato\"), eq(15))).thenReturn(List.of(doc));\n\n        assertThat(servicio(documentos).buscarPorTitulo(\"  contrato \")).containsExactly(doc);\n    }\n\n    private static DocumentosService servicio(DocumentoRepositorio documentos) {\n        return new DocumentosService(documentos, mock(AlmacenDocumentos.class), mock(PublicadorEventos.class),\n                Clock.systemUTC(), new SimpleMeterRegistry(), 30);\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/documentos/config/RelojConfigTest.java": "package com.mx.josesaid.develop.documentos.config;\n\nimport static org.junit.jupiter.api.Assertions.assertEquals;\n\nimport java.time.ZoneId;\nimport org.junit.jupiter.api.Test;\n\nclass RelojConfigTest {\n\n    @Test\n    void relojUsaLaZonaDeOperacion() {\n        assertEquals(ZoneId.of(\"America/Mexico_City\"), new RelojConfig().reloj().getZone());\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/documentos/domain/DocumentoTest.java": "package com.mx.josesaid.develop.documentos.domain;\n\nimport static org.junit.jupiter.api.Assertions.assertEquals;\nimport static org.junit.jupiter.api.Assertions.assertFalse;\nimport static org.junit.jupiter.api.Assertions.assertThrows;\nimport static org.junit.jupiter.api.Assertions.assertTrue;\n\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport java.util.UUID;\nimport org.junit.jupiter.api.Test;\n\nclass DocumentoTest {\n\n    private static final UUID ID = UUID.randomUUID();\n    private static final LocalDate HOY = LocalDate.of(2026, 1, 1);\n    private static final Instant AHORA = Instant.parse(\"2026-01-01T00:00:00Z\");\n\n    private static Documento contrato() {\n        return Documento.crear(ID, TipoDocumento.CONTRATO, \"Contrato marco\", \"Administración y legal\",\n                null, HOY, \"hash1\", \"ref1\", AHORA);\n    }\n\n    private static Documento permiso(LocalDate venceEn) {\n        return Documento.crear(ID, TipoDocumento.PERMISO, \"Permiso ambiental\", \"Operaciones\",\n                venceEn, HOY, \"hash1\", \"ref1\", AHORA);\n    }\n\n    @Test\n    void creaVersionUnoYRetencionSegunTipo() {\n        Documento d = contrato();\n        assertEquals(1, d.getVersionActual());\n        assertEquals(LocalDate.of(2036, 1, 1), d.getRetencionHasta());\n    }\n\n    @Test\n    void unPermisoRequiereFechaDeVencimiento() {\n        assertThrows(ReglaDeNegocioException.class, () -> permiso(null));\n    }\n\n    @Test\n    void unaNuevaVersionIncrementaElNumero() {\n        Documento d = contrato();\n        VersionDocumento v = d.agregarVersion(\"hash2\", \"ref2\", HOY, AHORA);\n        assertEquals(2, v.numero());\n        assertEquals(2, d.getVersionActual());\n    }\n\n    @Test\n    void elMismoContenidoNoCreaVersion() {\n        Documento d = contrato();\n        assertThrows(ConflictoException.class, () -> d.agregarVersion(\"hash1\", \"ref2\", HOY, AHORA));\n    }\n\n    @Test\n    void unDocumentoVencidoNoRecibeVersiones() {\n        Documento p = permiso(LocalDate.of(2026, 3, 1));\n        assertThrows(ConflictoException.class,\n                () -> p.agregarVersion(\"hash2\", \"ref2\", LocalDate.of(2026, 4, 1), AHORA));\n    }\n\n    @Test\n    void eliminarDentroDeRetencionDevuelveConflicto() {\n        assertThrows(ConflictoException.class,\n                () -> contrato().eliminar(\"Solicitud\", LocalDate.of(2030, 1, 1), AHORA));\n    }\n\n    @Test\n    void eliminarRequiereMotivo() {\n        assertThrows(SolicitudInvalidaException.class,\n                () -> contrato().eliminar(\"   \", LocalDate.of(2040, 1, 1), AHORA));\n    }\n\n    @Test\n    void eliminarDespuesDeLaRetencionMarcaElDocumento() {\n        Documento d = contrato();\n        d.eliminar(\"Fin de retención\", LocalDate.of(2037, 1, 1), AHORA);\n        assertTrue(d.isEliminado());\n    }\n\n    @Test\n    void unPermisoPorVencerGeneraAlertaUnaSolaVez() {\n        Documento p = permiso(HOY.plusDays(10));\n        assertTrue(p.necesitaAlertaVencimiento(HOY, 30));\n        p.registrarAlertaVencimiento();\n        assertFalse(p.necesitaAlertaVencimiento(HOY, 30));\n    }\n\n    @Test\n    void unContratoNoGeneraAlertaDeVencimiento() {\n        assertFalse(contrato().necesitaAlertaVencimiento(HOY, 30));\n    }\n\n    @Test\n    void laRetencionVencidaSeMarcaParaRevisionUnaVez() {\n        Documento d = contrato();\n        LocalDate despues = LocalDate.of(2037, 1, 1);\n        assertTrue(d.necesitaRevisionRetencion(despues));\n        d.marcarRevisionRetencion();\n        assertFalse(d.necesitaRevisionRetencion(despues));\n    }\n\n    @Test\n    void purgarRequiereEliminacionPrevia() {\n        assertThrows(ConflictoException.class,\n                () -> contrato().purgar(ID.toString(), LocalDate.of(2037, 1, 1), AHORA));\n    }\n\n    @Test\n    void purgarExigeConfirmarConElIdentificador() {\n        Documento d = contrato();\n        d.eliminar(\"Fin de retención\", LocalDate.of(2037, 1, 1), AHORA);\n        assertThrows(SolicitudInvalidaException.class,\n                () -> d.purgar(\"otro\", LocalDate.of(2037, 1, 1), AHORA));\n        assertFalse(d.isPurgado());\n    }\n\n    @Test\n    void purgarMarcaElDocumentoYNoSeRepite() {\n        Documento d = contrato();\n        d.eliminar(\"Fin de retención\", LocalDate.of(2037, 1, 1), AHORA);\n        d.purgar(ID.toString(), LocalDate.of(2037, 1, 1), AHORA);\n        assertTrue(d.isPurgado());\n        assertEquals(AHORA, d.getPurgadoUtc());\n        assertThrows(ConflictoException.class,\n                () -> d.purgar(ID.toString(), LocalDate.of(2037, 1, 1), AHORA));\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/documentos/infrastructure/ProtectorArchivosTest.java": "package com.mx.josesaid.develop.documentos.infrastructure;\n\nimport static java.nio.charset.StandardCharsets.ISO_8859_1;\nimport static java.nio.charset.StandardCharsets.UTF_8;\nimport static org.junit.jupiter.api.Assertions.assertArrayEquals;\nimport static org.junit.jupiter.api.Assertions.assertFalse;\nimport static org.junit.jupiter.api.Assertions.assertThrows;\n\nimport com.mx.josesaid.develop.documentos.infrastructure.seguridad.ProtectorArchivos;\nimport java.util.Arrays;\nimport org.junit.jupiter.api.Test;\n\nclass ProtectorArchivosTest {\n\n    private static final String CLAVE = \"MDEyMzQ1Njc4OWFiY2RlZjAxMjM0NTY3ODlhYmNkZWY=\";\n\n    @Test\n    void cifraYDescifraSinPerderElContenido() {\n        ProtectorArchivos p = new ProtectorArchivos(CLAVE);\n        byte[] claro = \"contrato confidencial\".getBytes(UTF_8);\n        byte[] cifrado = p.cifrar(claro);\n        assertFalse(new String(cifrado, ISO_8859_1).contains(\"confidencial\"));\n        assertArrayEquals(claro, p.descifrar(cifrado));\n    }\n\n    @Test\n    void dosCifradosDelMismoContenidoSonDistintos() {\n        ProtectorArchivos p = new ProtectorArchivos(CLAVE);\n        byte[] claro = \"mismo contenido\".getBytes(UTF_8);\n        assertFalse(Arrays.equals(p.cifrar(claro), p.cifrar(claro)));\n    }\n\n    @Test\n    void detectaCualquierManipulacionDelArchivo() {\n        ProtectorArchivos p = new ProtectorArchivos(CLAVE);\n        byte[] cifrado = p.cifrar(\"dato\".getBytes(UTF_8));\n        cifrado[cifrado.length - 1] ^= 1;\n        assertThrows(IllegalStateException.class, () -> p.descifrar(cifrado));\n    }\n\n    @Test\n    void rechazaUnaClaveQueNoEsAes256() {\n        assertThrows(IllegalStateException.class, () -> new ProtectorArchivos(\"\"));\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/documentos/infrastructure/indicadores/PublicadorIndicadoresVencimientosIT.java": "package com.mx.josesaid.develop.documentos.infrastructure.indicadores;\n\nimport static org.junit.jupiter.api.Assertions.assertEquals;\n\nimport com.jayway.jsonpath.JsonPath;\nimport java.time.Duration;\nimport java.time.LocalDate;\nimport java.time.YearMonth;\nimport java.time.ZoneId;\nimport java.util.Collections;\nimport java.util.Properties;\nimport java.util.UUID;\nimport org.apache.kafka.clients.consumer.ConsumerConfig;\nimport org.apache.kafka.clients.consumer.KafkaConsumer;\nimport org.apache.kafka.common.serialization.StringDeserializer;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.context.SpringBootTest;\nimport org.springframework.boot.testcontainers.service.connection.ServiceConnection;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.testcontainers.junit.jupiter.Container;\nimport org.testcontainers.junit.jupiter.Testcontainers;\nimport org.testcontainers.kafka.KafkaContainer;\nimport org.testcontainers.postgresql.PostgreSQLContainer;\n\n/** Integración con PostgreSQL y Kafka reales (Testcontainers). Requiere Docker; corre con 'mvn verify'. */\n@SpringBootTest(properties = {\n        \"documentos.jwt.jwks-uri=http://localhost:9/.well-known/jwks.json\",\n        \"documentos.cifrado.clave=MDEyMzQ1Njc4OWFiY2RlZjAxMjM0NTY3ODlhYmNkZWY=\",\n        \"documentos.almacen.directorio=${java.io.tmpdir}/documentos-it-${random.uuid}\"})\n@Testcontainers\nclass PublicadorIndicadoresVencimientosIT {\n\n    @Container\n    @ServiceConnection\n    static PostgreSQLContainer postgres = new PostgreSQLContainer(\"postgres:17-alpine\");\n\n    @Container\n    @ServiceConnection\n    static KafkaContainer kafka = new KafkaContainer(\"apache/kafka:4.0.0\");\n\n    @Autowired\n    private JdbcTemplate jdbc;\n\n    @Autowired\n    private PublicadorIndicadoresVencimientos publicador;\n\n    private static final ZoneId ZONA = ZoneId.of(\"America/Mexico_City\");\n\n    @Test\n    void documentosPorVencerCuentaSoloVigentesDentroDe30Dias() {\n        LocalDate hoy = LocalDate.now(ZONA);\n        String periodo = YearMonth.from(hoy).toString();\n        documento(hoy.plusDays(10), false, null);            // cuenta\n        documento(hoy.plusDays(60), false, null);            // fuera de rango\n        documento(hoy.plusDays(5), true, \"Duplicado\");       // excluido: eliminado\n        documento(hoy.minusDays(1), false, null);            // excluido: ya venció\n\n        publicador.publicar();\n\n        String clave = PublicadorIndicadoresVencimientos.AREA + \"|\" + PublicadorIndicadoresVencimientos.NOMBRE + \"|\" + periodo;\n        String payload = leerIndicador(clave);\n        assertEquals(\"ADMINISTRACION_LEGAL\", JsonPath.read(payload, \"$.area\"));\n        assertEquals(1.0, ((Number) JsonPath.read(payload, \"$.valor\")).doubleValue(), 0.001);\n    }\n\n    private void documento(LocalDate venceEn, boolean eliminado, String motivo) {\n        jdbc.update(\"\"\"\n                INSERT INTO documentos (id, tipo, titulo, area, vence_en, retencion_hasta, eliminado,\n                                        motivo_eliminacion, version)\n                VALUES (?, 'CONTRATO', 'Contrato', 'Legal', ?, ?, ?, ?, 0)\n                \"\"\", UUID.randomUUID(), java.sql.Date.valueOf(venceEn),\n                java.sql.Date.valueOf(LocalDate.now(ZONA).plusYears(10)), eliminado, motivo);\n    }\n\n    private String leerIndicador(String clave) {\n        try (KafkaConsumer<String, String> consumidor = new KafkaConsumer<>(propiedades())) {\n            consumidor.subscribe(Collections.singletonList(\"indicadores-areas\"));\n            long limite = System.currentTimeMillis() + 30_000;\n            while (System.currentTimeMillis() < limite) {\n                for (var registro : consumidor.poll(Duration.ofMillis(500))) {\n                    if (clave.equals(registro.key())) {\n                        return registro.value();\n                    }\n                }\n            }\n            throw new AssertionError(\"No llegó el indicador \" + clave);\n        }\n    }\n\n    private Properties propiedades() {\n        Properties p = new Properties();\n        p.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, kafka.getBootstrapServers());\n        p.put(ConsumerConfig.GROUP_ID_CONFIG, \"test-\" + UUID.randomUUID());\n        p.put(ConsumerConfig.AUTO_OFFSET_RESET_CONFIG, \"earliest\");\n        p.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);\n        p.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);\n        return p;\n    }\n}\n"};
